window.DBD_DATA.perks.push(...[{"id":"will-to-live","rank":1,"tier":"S+","roles":["Anti-Tunnel","Chase"],"summary":"After an unhook, a successful Skill Check when the Killer picks you up can free you and stun them once.","metaStatus":"Elite","skillLevel":"Low–Medium","soloQ":5,"swf":5,"unlockPriority":"Immediate","glossaryKeys":["tunneling","anti-tunnel","conspicuous-action","hook-state"],"useCases":["Punish direct tunneling after an unhook.","Buy a fresh chase after the Killer commits to a pickup.","Force the Killer to consider slugging or switching targets."],"counters":["The Killer can leave you slugged until the timer expires.","Conspicuous Actions disable it.","It is disabled once the Exit Gates are powered.","A missed Skill Check wastes the opportunity."],"pros":["Directly attacks one of the strongest Killer win conditions.","Changes Killer decision-making even before it actually triggers.","Works in Solo Q without teammate setup."],"cons":["Can provide zero direct value if the Killer does not tunnel.","Once-per-Trial successful use.","Good Killers may play around the pickup window."],"analysis":["Will to Live earns the top slot because tunneling is not merely annoying behavior; it is one of the fastest ways a Killer can convert an even match into a 3v1. A perk that makes that conversion less reliable changes the strategic shape of the match even when it never fires.","Its hidden strength is threat value. Once a Killer respects the possibility of Will to Live, they may leave a recently unhooked Survivor on the ground, delay the pickup, or chase someone else. Every one of those responses can buy the Survivor team time. That is why its impact is larger than the four-second stun written on the perk.","For newer players, the only mechanical demand is landing the Skill Check. For experienced players, the skill is in managing the active window: route toward safer tiles, avoid unnecessary Conspicuous Actions, understand when the Killer is likely to slug, and use the threat to create distance rather than merely chase a dramatic stun.","Solo Q benefits enormously because the perk does not require communication. SWF can extract even more value by coordinating bodyblocks, resets, and generator pressure around a tunneled teammate. The main caveat is that a Killer who spreads pressure may never trigger it, but forcing healthy Killer behavior is itself meaningful value."],"verdict":"The best general anti-tunnel insurance in the current live game. If you expect to be chased off hook, it is one of the safest high-impact slots you can equip.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["resurgence","off-the-record","unbreakable","sprint-burst"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Resurgence","Off the Record","Unbreakable","Sprint Burst"],"antiSynergies":[],"name":"Will to Live","alternateName":"Decisive Strike","source":"General perk / Laurie Strode licensed display","status":"Live 10.2.0","currentEffect":"After you are unhooked or unhook yourself, the perk activates for 40/50/60 seconds. If the Killer grabs or picks you up during that window, succeed at the Skill Check to escape their grasp and stun the Killer for 4 seconds. Using the perk makes you the next Obsession and disables the perk for the rest of the Trial. It deactivates when the Exit Gates are powered or when you perform a Conspicuous Action. It also increases your chance of being the initial Obsession by 100% of the default value.","activation":["Be unhooked or unhook yourself.","Be grabbed or picked up by the Killer during the 40/50/60-second activation window and succeed at the Skill Check.","Ends/deactivates when: Deactivates when Exit Gates are powered.","Ends/deactivates when: Deactivates if you perform a Conspicuous Action.","Ends/deactivates when: After use, disabled for the remainder of the Trial."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified for the current general-perk version from available patch history.","plainEnglishSummary":"After an unhook, a successful Skill Check when grabbed or picked up can stun the Killer and let you escape once.","cooldown":null,"duration":["Activation window after unhook: 40/50/60 seconds.","Killer stun: 4 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Can be used once per Trial; after use it is disabled for the remainder of the Trial.","statusEffectsInvolved":[],"specialInteractions":["Successful use makes you the next Obsession.","The Killer can have only one Obsession at a time."],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"lithe","rank":2,"tier":"S","roles":["Chase","Exhaustion","Mobility"],"summary":"A Rushed Vault gives 50% Haste for 3 seconds, letting you turn a window or pallet vault into a major burst of distance.","metaStatus":"Elite","skillLevel":"Low–Medium","soloQ":5,"swf":5,"unlockPriority":"Very High","glossaryKeys":["haste","exhausted","looping"],"useCases":["Break line of sight after reaching a strong window.","Use a mediocre vault as a launch point toward a safer tile.","Escape zoning by vaulting back through a stunned pallet when the path is available."],"counters":["You need a usable vault before the perk can trigger.","Poor vault timing can spend Lithe without creating meaningful distance.","Exhausted blocks another activation until it recovers.","Hex: Under Your Thumb can cap running Haste while the Hex remains lit."],"pros":["Simple, reliable, and fully under your control in most chases.","Still grants 3 seconds of Haste while Sprint Burst was reduced to 2 seconds in 10.1.","Excellent for newer, returning, and experienced players."],"cons":["Requires a Rushed Vault, so dead zones can deny it.","Can accidentally trigger on a vault you would rather loop normally.","Does not help before you reach a vaultable resource."],"analysis":["Lithe is the reliability pick of this batch. It lacks Dead Hard's spectacular extra-hit ceiling and Five Moves Ahead's resource intelligence, but it asks very little from the player: reach a vault, use it at the right time, and receive three seconds of 50% Haste.","That three-second duration matters more after Sprint Burst's 10.1 nerf to two seconds. Sprint Burst remains higher because it can protect unsafe generators and prevent a chase from starting badly, but once a chase is established Lithe offers a very controllable way to relocate across the map.","The main skill is not pressing the button. It is choosing which vault deserves the activation. Using Lithe on a strong loop too early may throw away both the loop and the perk. Using a weak or isolated window as a launch point can instead convert a bad area into access to a much stronger tile.","Current usage data places Lithe among the most commonly equipped Survivor perks on 10.1, which fits its broad appeal. It is easy to understand, rarely completely dead, and useful at nearly every experience level."],"verdict":"One of the safest chase recommendations for a rusty or newer Survivor. It is less timing-sensitive than Dead Hard and converts into useful distance in a very wide range of matches.","publicationStatus":"published","tags":["Positioning"],"queueRatingStatus":"reviewed","rankRange":[2,4],"rankConfidence":"High","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Feng Min"},"synergyPerkIds":["windows-of-opportunity","five-moves-ahead","dance-with-me","quick-quiet"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"synergies":["Windows of Opportunity","Five Moves Ahead","Dance With Me","Quick & Quiet"],"antiSynergies":[],"name":"Lithe","alternateName":null,"source":"Feng Min","status":"Live 10.2.0","currentEffect":"Whenever you perform a Rushed Vault action while not Exhausted, gain 50% Haste for 3 seconds. Lithe cannot be used while Exhausted and causes Exhausted for 60/50/40 seconds by tier.","activation":["Perform a Rushed Vault action.","Not be suffering from Exhausted.","Ends/deactivates when: The Haste effect ends after 3 seconds; Exhausted prevents triggering Lithe again until it expires."],"patchNote":"Latest live balance change (2.6.0): Removed the Chase requirement; Lithe now triggers only on Rushed Vaults.","plainEnglishSummary":"A Rushed Vault grants a brief speed boost and then Exhausted prevents reuse until it expires.","cooldown":null,"duration":["Haste: 3 seconds.","Exhausted: 60/50/40 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste","Exhausted"],"specialInteractions":["The activation requires a Rushed Vault; it does not require being in a Chase."],"sourceCharacter":"Feng Min","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"dead-hard","rank":3,"tier":"S","roles":["Chase","Exhaustion"],"summary":"After an unhook, time a 0.5-second Endurance window while injured and running to survive an otherwise downing hit.","metaStatus":"Elite","skillLevel":"High","soloQ":5,"swf":5,"unlockPriority":"Very High","glossaryKeys":["endurance","exhausted","deep-wound","looping","hook-state"],"useCases":["Turn a committed Killer attack into another full chase segment.","Force difficult swing-or-wait decisions at pallets and tight loops.","Punish powers with narrow attack windows when your timing is sharp."],"counters":["The 0.5-second timing window is unforgiving.","It cannot be used while Exhausted.","If you are already in Deep Wound, Endurance cannot save you from another damaging hit in the usual way.","It is unavailable until you have been unhooked."],"pros":["Can effectively create an extra health state when timed correctly.","Remains available after normal objectives once armed until you use it.","Gets stronger with player skill and matchup knowledge."],"cons":["High execution requirement and vulnerable to Killer baiting.","Not available before your first unhook.","Competes with other Exhaustion perks."],"analysis":["Dead Hard remains one of the highest-ceiling Survivor perks because a successful activation is not merely movement speed. It can erase an attack that should have ended the chase and convert that moment into another pallet, window, or rotation.","Against certain powers, however, the timing becomes much more favorable. Killers who commit to a narrow attack window give experienced Survivors a clearer reaction point, which is why Dead Hard can feel more oppressive against some top-end Killers than it does against a patient basic attacker.","It also pairs extremely well with anti-tunnel tools. Will to Live can force the Killer to pick you up and restart the chase, while Dead Hard remains a later defensive layer once you are injured again. That combination makes a tunneled Survivor substantially harder to remove."],"verdict":"An elite-ceiling chase perk for players with strong reactions and Killer matchup knowledge. Its activation and execution requirements keep the average value below the absolute easiest chase options.","publicationStatus":"published","tags":["Second Chance"],"queueRatingStatus":"reviewed","rankRange":[2,5],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"David King"},"synergyPerkIds":["will-to-live","five-moves-ahead","resilience","made-for-this"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"synergies":["Will to Live","Five Moves Ahead","Resilience","Made for This"],"antiSynergies":[],"name":"Dead Hard","alternateName":null,"source":"David King","status":"Live 10.2.0","currentEffect":"After being unhooked by any means, while injured and running press the Active Ability button to gain Endurance for 0.5 seconds. Cannot be used while Exhausted and causes Exhausted for 60/50/40 seconds.","activation":["Be unhooked by any means.","Be injured and running when using Active Ability.","You must not be Exhausted.","Ends/deactivates when: The Endurance effect ends after 0.5 seconds.","Ends/deactivates when: The activation is consumed when used; a later unhook can reactivate the perk if its conditions are met."],"patchNote":"Latest live balance change (6.7.0): Restricted activation to after being unhooked.","plainEnglishSummary":"After an unhook, an injured running Survivor can activate a brief Endurance window.","cooldown":null,"duration":["Endurance: 0.5 seconds.","Exhausted: 60/50/40 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Endurance","Exhausted"],"specialInteractions":[],"sourceCharacter":"David King","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"resurgence","rank":4,"tier":"S","roles":["Healing"],"summary":"Every unhook instantly gives you 50/60/70% of a full heal worth of progress.","metaStatus":"Elite","skillLevel":"Low","soloQ":5,"swf":5,"unlockPriority":"Very High","glossaryKeys":["reset","hook-state","health-state"],"useCases":["Rapid post-unhook resets.","Punish Killers who leave hook after securing pressure elsewhere.","Reduce the time two Survivors spend healing instead of repairing generators."],"counters":["Haemorrhage can erase stored healing progress if you are not healed quickly.","A Killer who immediately tunnels may deny the reset window.","Broken prevents completing the heal until it ends."],"pros":["Extremely consistent on normal unhooks.","Saves both your time and the healer’s time.","Requires almost no mechanical execution."],"cons":["Does nothing before your first unhook.","Healing progress can be lost to Haemorrhage.","Less valuable if you intentionally stay injured."],"analysis":["Resurgence looks simple because it is simple, and that is exactly why it ranks so highly. A Tier III proc begins the post-unhook heal at 70%, turning what would normally be a substantial two-player reset into a very short interaction. That time saving compounds because two Survivors are freed to repair, rescue, or reposition earlier.","Unlike many strong perks, Resurgence does not ask for a difficult trigger, map condition, or teammate communication. Getting unhooked is a normal match event. The perk converts that unavoidable event into reliable tempo, making it one of the cleanest examples of a high-floor perk with genuine top-end strength.","The biggest practical counter is Haemorrhage. If the team hesitates after the unhook, the stored progress can bleed away. The second is direct tunneling, where there may be no safe opportunity to finish the heal. That is why Resurgence pairs so naturally with anti-tunnel perks: one protects your reset window while the other makes the reset almost instantaneous.","In Solo Q, its predictability is gold because random teammates only need to recognize that you are nearly healed. In SWF, the team can deliberately plan short resets around it. For players choosing unlocks, Jill offers one of the most universally useful perks in the game."],"verdict":"An elite time-efficiency perk. If you are normally healed after unhooks, Resurgence turns one of the match’s most common downtime moments into a tiny speed bump.","publicationStatus":"published","tags":["Reset"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Jill Valentine"},"synergyPerkIds":["will-to-live","well-make-it","botany-knowledge"],"synergyOther":["Med-Kits"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Will to Live","We'll Make It","Botany Knowledge","Med-Kits"],"antiSynergies":[],"name":"Resurgence","alternateName":null,"source":"Jill Valentine","status":"Live 10.2.0","currentEffect":"After you are unhooked by any means, Resurgence instantly grants you healing progression equal to 50/60/70% of a full health state, according to perk tier.","activation":["Be unhooked by any means, including an unhook performed by yourself.","Ends/deactivates when: The granted healing progression is applied immediately; no continuing effect remains."],"patchNote":"Latest live balance change (8.1.0): Increased healing progression granted to 50/60/70% from 40/45/50%.","plainEnglishSummary":"Being unhooked instantly fills 50/60/70% of your healing progress, depending on perk tier.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Triggers on each time you are unhooked; no once-per-Trial limit is specified.","statusEffectsInvolved":[],"specialInteractions":["The granted amount is healing progression, not a healing-speed bonus."],"sourceCharacter":"Jill Valentine","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"unbreakable","rank":5,"tier":"S","roles":["Anti-Slug","Utility"],"summary":"Recover faster after the Killer downs you and fully pick yourself up once per Trial.","metaStatus":"Elite","skillLevel":"Low","soloQ":5,"swf":5,"unlockPriority":"Very High","glossaryKeys":["slugging","anti-slug","dying-state","snowball"],"useCases":["Stop multi-Survivor slug snowballs.","Punish Killers who leave you downed to chase another Survivor.","Create a surprise recovery during endgame or pickup-denial situations."],"counters":["A Killer who hooks promptly can deny the self-pickup.","The once-per-Trial recovery can be baited out early.","Some Killers can return before you finish recovering."],"pros":["Can single-handedly reverse a losing slug situation.","Faster recovery provides value even if a teammate completes the pickup.","Very easy to use correctly."],"cons":["Can be a dead slot against Killers who never slug.","Full recovery is limited to one use.","Requires the Killer to cause the Dying State under the current version."],"analysis":["Unbreakable is the classic anti-slug benchmark because it attacks the exact moment when Killer pressure is most likely to snowball. One Survivor down is manageable. Two or three Survivors down at once can end the match. The ability to stand up without another teammate can break that chain entirely.","The 25/30/35% recovery-speed bonus matters more than the dramatic self-pickup gets credit for. Even when a teammate is coming to rescue you, faster recovery reduces the time they must spend finishing the pickup. In other words, the perk has a smaller efficiency benefit before it ever cashes in its once-per-Trial headline effect.","Its weakness is pure matchup consistency. Some Killers hook almost every down immediately, and in those matches the perk may do very little. But when slugging is the correct Killer play, Unbreakable can transform a match-losing position into a reset. That ceiling is high enough to keep it near the top despite occasional zero-value games.","For Solo Q, the independence is especially important because you cannot guarantee that a random teammate understands when to stop a gen and pick you up. SWF teams can deliberately exploit the threat of Unbreakable to make aggressive pickup-denial and bodyblock plays much safer."],"verdict":"The premier anti-slug perk. It is not guaranteed to trigger every match, but when the Killer tries to snowball on the ground, few Survivor perks can swing the game harder.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"William \"Bill\" Overbeck"},"synergyPerkIds":["will-to-live","tenacity","soul-guard","flip-flop"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Will to Live","Tenacity","Soul Guard","Flip-Flop"],"antiSynergies":[],"name":"Unbreakable","alternateName":null,"source":"William \"Bill\" Overbeck","status":"Live 10.2.0","currentEffect":"When the Killer puts you into the Dying State, increases your Recovery speed by 25/30/35%, unlocks Self-Recovery to fully recover from the Dying State, and limits that full recovery to once per Trial.","activation":["The Killer must put you into the Dying State.","Ends/deactivates when: The full Self-Recovery ability is consumed after one use in the Trial."],"patchNote":"Latest live balance change (9.5.0): Restricted activation to when the Killer puts you into the Dying State.","plainEnglishSummary":"After the Killer downs you, you recover faster and can pick yourself up from the Dying State once per Trial.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Full Self-Recovery can be used once per Trial.","statusEffectsInvolved":[],"specialInteractions":["The current activation condition specifies being put in the Dying State by the Killer."],"sourceCharacter":"William \"Bill\" Overbeck","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"sprint-burst","rank":6,"tier":"S","roles":["Chase","Exhaustion"],"summary":"Starting to run gives 50% Haste for 2 seconds, then applies Exhausted.","metaStatus":"Elite","skillLevel":"Medium","soloQ":5,"swf":5,"unlockPriority":"Very High","glossaryKeys":["haste","exhausted","looping","pressure"],"useCases":["Reach a safe tile before the Killer can begin a clean chase.","Work on otherwise dangerous generators and escape when approached.","Create enough opening distance to force the Killer to abandon pressure."],"counters":["Poor timing can trigger it when you did not need it.","Walking everywhere to preserve it can cost more time than the perk saves.","Exhaustion management limits repeated use.","Hex: Under Your Thumb can cap running Haste while the Hex remains lit."],"pros":["Works on every map and against every Killer.","Creates distance before the chase becomes dangerous.","No vault, fall, or pallet requirement."],"cons":["Requires discipline to manage without becoming overly passive.","The 10.1.0 duration nerf reduced total distance.","Shares Exhausted with other major chase perks."],"analysis":["Sprint Burst remains the most flexible Exhaustion perk even after its 10.1.0 nerf from three seconds to two. Its advantage is not simply raw distance. It lets you decide where the chase begins. That is a huge strategic benefit because the safest Survivor is often the one who never allows the Killer a free first hit near a dead zone.","The common beginner mistake is treating Sprint Burst as a precious consumable and walking across the map to preserve it. That often loses more generator and rotation time than the perk can repay. Strong Sprint Burst play accepts ordinary activations, recovers Exhausted naturally, and saves deliberate 99% Exhaustion management for moments where it actually matters.","Compared with Lithe or Balanced Landing, Sprint Burst has no environmental trigger requirement. That universal availability is why it stays near the top even with less Haste duration. Experienced players can also use it proactively to repair unsafe generators, greed positioning, or bait the Killer into approaching before launching toward a stronger tile.","Solo Q gets reliable self-sufficiency from it, while SWF can use comms to coordinate dangerous generators and chase rotations. The perk has a medium skill floor only because misuse can create bad habits; its mechanical activation itself is effortless."],"verdict":"Still an elite chase and positioning perk after the 10.1 nerf. Use it freely enough that it creates tempo instead of turning you into a full-time walker.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":[4,8],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Meg Thomas"},"synergyPerkIds":["vigil","fixated","bond","adrenaline"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"synergies":["Vigil","Fixated","Bond","Adrenaline"],"antiSynergies":[],"name":"Sprint Burst","alternateName":null,"source":"Meg Thomas","status":"Live 10.2.0","currentEffect":"Starting to run triggers Sprint Burst and grants 50% Haste for 2 seconds. It cannot be used while Exhausted and applies Exhausted for 60/50/40 seconds.","activation":["Start running while not Exhausted.","Ends/deactivates when: Haste ends after 2 seconds; another activation is unavailable until Exhausted is recovered."],"patchNote":"Latest live balance change (10.1.0): Reduced the Haste duration from 3 seconds to 2 seconds.","plainEnglishSummary":"Starting to run gives you a two-second speed burst and causes Exhausted.","cooldown":null,"duration":["Haste: 2 seconds.","Exhausted: 60/50/40 seconds, with recovery governed by Exhausted rules."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste","Exhausted"],"specialInteractions":["Uses the shared Exhausted status effect; running slows Exhausted recovery under the current Exhaustion rules."],"sourceCharacter":"Meg Thomas","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"resilience","rank":7,"tier":"A","roles":["Objective","Chase"],"summary":"While injured, gain a broad 9% speed boost to important actions, including repairs and vaults.","metaStatus":"Strong","skillLevel":"Medium","soloQ":4,"swf":4,"unlockPriority":"Immediate","glossaryKeys":["health-state","looping","pressure"],"useCases":["Convert time spent injured into faster generator progress instead of immediately abandoning the objective to heal.","Use the vault-speed bonus to tighten chase timings at windows and pallets.","Accelerate late-game interactions such as opening gates or rescuing when every second matters."],"counters":["The perk provides no value while Healthy, so players who heal immediately after every injury may waste the slot.","Staying injured to preserve the bonus makes one-hit downs and stealth approaches more dangerous.","Killers or powers that punish injured Survivors can make intentionally holding the Injured State a poor trade."],"pros":["Affects many of the actions that decide matches instead of only one narrow interaction.","The vault-speed bonus has direct chase value while the repair bonus creates macro value at the same time.","It is a General perk, so the unlock cost is effectively zero."],"cons":["Requires being Injured.","Encourages a riskier playstyle that is less forgiving for newer players.","The individual 9% bonuses are strong through accumulation rather than one dramatic activation."],"analysis":["Resilience earns this position because very few Survivor perks turn one ordinary match state into value across so many different parts of the game. Being injured is unavoidable in most Trials, and Resilience converts that state into faster repairs, vaults, heals, unhooks, gates, and several secondary interactions. That breadth makes it useful whether the match is currently about generators, chase, rescue, or endgame.","Its chase value is easy to underrate. Nine percent faster vaulting can change whether a window is barely safe or barely a hit, especially at strong tiles where both players are contesting a very small timing margin. It is not as explosive as an Exhaustion perk or Finesse, but it is always present while injured and asks for no cooldown management.","The macro value is just as important. Survivors often spend long stretches injured while repairing, particularly against Killers where stopping for every heal loses too much tempo. In those matches, Resilience quietly adds generator progress while still improving the user's next chase. That dual-purpose value is why it remains stronger than perks that only help one job.","The drawback is real: the perk tempts players to stay one hit from the Dying State. Experienced players can judge when that risk is acceptable; newer players may give away more downs than the speed bonus ever repays. Resilience is strongest when the user already understands when to heal and when to deliberately keep working injured."],"verdict":"One of the best all-purpose injured-state perks in the game. Resilience rewards confident players with chase and objective value from the same slot, but its ceiling depends on knowing when staying injured is actually safe.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","rank-review-applied","queue-rating:normalized-tier-plus-v14-specialization-signal"],"tags":["Efficiency"],"queueRatingStatus":"reviewed","rankRange":[6,12],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["dead-hard","iron-will","finesse","deja-vu"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Dead Hard","Iron Will","Finesse","Déjà Vu"],"antiSynergies":[],"name":"Resilience","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"While Injured, you Bless and Cleanse Totems, heal, open Exit Gates, repair Generators, sabotage Hooks, unhook Survivors, unlock Chests, and vault 7/8/9% faster.","activation":["Be in the Injured State while performing one of the listed actions.","Ends/deactivates when: The speed bonus ends when you are no longer in the Injured State or stop performing an affected action."],"patchNote":"Latest live balance change (10.2.0): Raised all listed Injured-state action-speed bonuses from 3/6/9% to 7/8/9%.","plainEnglishSummary":"While injured, perform a broad set of interactions and vaults 7/8/9% faster.","cooldown":null,"duration":["While Injured and performing an affected action."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"adrenaline","rank":8,"tier":"A","roles":["Endgame","Healing","Chase"],"summary":"When the Exit Gates are powered, recover one Health State if eligible and gain 50% Haste for 4 seconds.","metaStatus":"Strong","skillLevel":"Low","soloQ":4,"swf":5,"unlockPriority":"Very High","glossaryKeys":["health-state","haste","exhausted","swf","solo-q"],"useCases":["Turn the final generator into an instant reset and chase extension.","Recover from the Dying State as the gates power.","Coordinate the final generator around a teammate currently in chase."],"counters":["Provides no value if the team never powers the gates.","Broken can prevent the healing component.","Being hooked or carried at gate power prevents activation.","Hex: Under Your Thumb can cap running Haste while the Hex remains lit."],"pros":["Combines healing and mobility in one instant trigger.","Can activate while already Exhausted.","Exceptionally strong when the last generator is deliberately timed."],"cons":["Entire perk slot is dormant until endgame.","Solo Q cannot always control when the final generator pops.","Hooked or carried Survivors miss the activation."],"analysis":["Adrenaline is the definition of delayed power. For most of the Trial it does nothing, but when the gates are powered it can instantly erase a health-state deficit and create four seconds of 50% Haste. That combination can convert a losing endgame chase into an escape or turn a slug into a Survivor who is suddenly standing and moving at high speed.","Its 10.1.0 buff to four seconds of Haste matters because endgame positions are often decided by a few metres. The extra second increases the odds of reaching a gate, strong tile, or teammate protection before the Killer can capitalize on the final generator completing.","The Solo Q weakness is timing control. A random teammate may finish the last generator while you are hooked, being carried, or seconds away from a safer activation. In SWF, that weakness almost disappears because the team can 99% the final gen, communicate the chase state, and trigger Adrenaline at the exact moment it creates maximum value.","Adrenaline also pairs naturally with Sprint Burst because it ignores an existing Exhausted timer when it activates. Meg therefore offers two top-five perks that cover opposite halves of the match: Sprint Burst for repeated positioning and Adrenaline for the decisive endgame swing."],"verdict":"One of the strongest endgame perks available. It asks you to carry a dormant slot for most of the match, then repays that investment with a potentially match-winning heal and speed burst.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Meg Thomas"},"synergyPerkIds":["sprint-burst","hope","resilience"],"synergyOther":["Endgame coordination"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Sprint Burst","Hope","Resilience","Endgame coordination"],"antiSynergies":[],"name":"Adrenaline","alternateName":null,"source":"Meg Thomas","status":"Live 10.2.0","currentEffect":"When the Exit Gates are powered, heal one Health State if you are injured or in the Dying State, then gain 50% Haste for 4 seconds. Adrenaline can activate while Exhausted and ignores the existing Exhausted timer; afterward it applies Exhausted for 60/50/40 seconds by tier. It does not activate if you are hooked or being carried when the Exit Gates are powered.","activation":["The Exit Gates are powered.","You are not hooked or being carried when the Exit Gates are powered; if injured or in the Dying State, the heal restores one Health State.","Ends/deactivates when: Haste ends after 4 seconds."],"patchNote":"Latest live balance change (10.1.0): Increased the Haste duration to 4 seconds.","plainEnglishSummary":"When the Exit Gates are powered, you recover one Health State if injured or downed and gain 50% Haste for 4 seconds; it will not activate if you are hooked or being carried at that moment and it applies tier-scaled Exhausted.","cooldown":null,"duration":["Haste: 4 seconds.","Exhausted: 60/50/40 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste","Exhausted"],"specialInteractions":["Can activate while Exhausted and ignores the current Exhausted timer; after activation, applies Exhausted for 60/50/40 seconds by tier.","The former Dream World wake-up effect was removed."],"sourceCharacter":"Meg Thomas","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"made-for-this","rank":9,"tier":"A","roles":["Chase","Healing"],"summary":"While injured, healing another Survivor can grant Endurance, and Deep Wound lets you run slightly faster.","metaStatus":"Strong","skillLevel":"High","soloQ":3,"swf":5,"unlockPriority":"High","glossaryKeys":["endurance","deep-wound","haste","health-state"],"useCases":["Heal a teammate while injured and use the resulting Endurance to survive a dangerous follow-up interaction.","Convert Deep Wound from an anti-tunnel or protection-hit event into a 3% chase-speed advantage.","Stack several connected team actions into a powerful mid-match rescue or anti-slug sequence."],"counters":["Its Haste requires both being Injured and suffering from Deep Wound.","The Endurance portion requires you to finish healing another Survivor while injured.","Conspicuous Actions can remove the granted Endurance early, limiting offensive abuse."],"pros":["Can provide both chase speed and an extra protected hit from one perk slot.","Scales dramatically inside coordinated rescue and anti-slug sequences.","The 3% Haste is small numerically but meaningful in a prolonged chase."],"cons":["Much more conditional than its historical versions.","Solo Q cannot reliably manufacture the exact healing and Deep Wound situations it wants.","Often needs other perks or teammate behavior to reach its ceiling."],"analysis":["Made for This earns this position because its modern strength is not passive speed. It is a conditional combination of two effects that become dangerous when a build is designed around them: Endurance after healing another Survivor while injured, and 3% Haste while the user is in Deep Wound.","The Haste component matters because movement-speed differences compound around loops. Three percent does not look dramatic on the loadout screen, but over repeated rotations it can change whether the Killer closes distance before the next pallet or window. The catch is that the Survivor first needs Deep Wound, so the perk cannot be treated as permanent chase speed.","The Endurance component is where coordinated teams can become creative. WGLF pickups, For the People plays, protection-hit chains, and post-unhook sequences can put the user into the exact health states Made for This wants while also creating a reason to heal another Survivor. Those combinations can turn one rescue into several layers of protection.","That setup dependency is why it lands below simpler perks. In Solo Q, the correct injured teammate, heal opportunity, and timing may never line up. In SWF, those conditions can be planned, making the perk considerably more dangerous. Made for This is therefore a high-ceiling build piece rather than a universally reliable standalone slot."],"verdict":"Still genuinely strong, but now as a synergy perk rather than a plug-and-play movement perk. It belongs in coordinated Endurance and Deep Wound setups more than in generic Solo Q builds.","publicationStatus":"published","tags":["Endurance"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Gabriel Soma"},"synergyPerkIds":["dead-hard","were-gonna-live-forever","for-the-people","resilience"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Dead Hard","We're Gonna Live Forever","For the People","Resilience"],"antiSynergies":[],"name":"Made for This","alternateName":null,"source":"Gabriel Soma","status":"Live 10.2.0","currentEffect":"Activates while you are in the Injured State. While active, completing a Healing action on another Survivor grants Endurance for the tier duration; that Endurance ends early if you perform any Conspicuous Action. While active and suffering from Deep Wound, running grants the tier-specific Haste bonus.","activation":["Be in the Injured State.","Complete a Healing action on another Survivor to trigger Endurance.","Be suffering from Deep Wound and running to receive Haste.","Ends/deactivates when: The Endurance effect ends after its tier duration or early when you perform a Conspicuous Action.","Ends/deactivates when: The Haste effect applies only while running and suffering from Deep Wound; the perk otherwise remains available while injured."],"patchNote":"Latest live balance change (7.4.0): Haste now requires Deep Wound and applies while running; Exhausted no longer disables the perk.","plainEnglishSummary":"While injured, healing a teammate grants temporary Endurance, and running while Deep Wounded grants tier-scaled Haste.","cooldown":null,"duration":["Endurance: 6/8/10 seconds.","Haste: while running and suffering from Deep Wound; no separate duration is specified."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Endurance","Deep Wound","Haste"],"specialInteractions":["The Haste effect applies only to running, not other movement modes."],"sourceCharacter":"Gabriel Soma","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"finesse","rank":10,"tier":"A","roles":["Chase"],"summary":"While healthy, your Fast Vaults are significantly quicker, letting good pathing turn close hits into misses.","metaStatus":"Strong","skillLevel":"Medium–High","soloQ":4,"swf":4,"unlockPriority":"Very High","glossaryKeys":["looping","health-state"],"useCases":["Win tight window timings where the Killer would normally connect during the vault animation.","Extend the first health state of a chase before the Killer can force you injured.","Pair strong map knowledge with safer greed at windows that would otherwise be marginal."],"counters":["Finesse only works while Healthy, so it shuts off after the first injury until you heal.","The 30-second Tier III cooldown prevents repeated use at every vault in the same chase.","Poor pathing is not rescued by a faster vault if the Killer already has the angle or distance advantage."],"pros":["Can directly deny hits rather than merely save a small amount of time.","Rewards strong chase fundamentals and becomes more valuable as the player's pathing improves.","Pairs naturally with several already-strong chase perks."],"cons":["Healthy-only activation limits uptime.","Cooldown means the user must choose which vault deserves the effect.","Less forgiving for players who do not already understand fast-vault angles and tile routing."],"analysis":["Finesse takes this position because its 20% Fast Vault bonus changes one of the most contested timings in Survivor chase. A vault that finishes slightly sooner can be the difference between preserving the Healthy State and giving the Killer a free first hit. That makes the perk more consequential than its simple description suggests.","The perk scales heavily with player skill. Newer Survivors can still benefit, but experienced loopers are better at identifying the exact window where the Killer must commit and at choosing a route that forces the Killer to respect the faster animation. In strong hands, Finesse turns already-good windows into extremely awkward hit timings.","Its limitations keep it below the very top chase perks. It only works while Healthy and then enters a 30-second cooldown, so it cannot carry an entire chase by itself. The user also needs to reach a Fast Vault in the first place. A Killer who zones the Survivor away from windows or secures the first hit in open space bypasses most of the perk's value.","Finesse is especially attractive because it combines cleanly with existing meta tools. Lithe converts the same vault into distance, while Windows or Five Moves Ahead help the Survivor reach the right structure. It is a focused perk rather than a universal one, but its focused job is extremely important."],"verdict":"A high-end chase perk for players who know how to route windows. Finesse does not fix bad positioning, but it makes good positioning substantially harder for the Killer to punish.","publicationStatus":"published","tags":["Vaulting"],"queueRatingStatus":"reviewed","rankRange":[8,14],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Lara Croft"},"synergyPerkIds":["lithe","windows-of-opportunity","five-moves-ahead","resilience"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Lithe","Windows of Opportunity","Five Moves Ahead","Resilience"],"antiSynergies":[],"name":"Finesse","alternateName":null,"source":"Lara Croft","status":"Live 10.2.0","currentEffect":"While healthy, your Fast Vaults are 20% faster. After performing a Fast Vault, Finesse goes on cooldown for 40/35/30 seconds.","activation":["You must be healthy to receive the Fast Vault speed bonus.","You must not be on cooldown.","Ends/deactivates when: The Fast Vault speed bonus is unavailable while injured or on cooldown."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"While healthy, you Fast Vault 20% faster, then the perk rests after a Fast Vault.","cooldown":"40/35/30 seconds (Tier I/II/III) after performing a Fast Vault.","duration":["The bonus applies during a Fast Vault action."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Lara Croft","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"shoulder-the-burden","rank":11,"tier":"A","roles":["Anti-Tunnel","Rescue","Team Support"],"summary":"Once per Trial, erase one Hook State from a teammate by taking it yourself; you become Injured and Broken, but other teammates can still use their own copy later.","metaStatus":"Strong","skillLevel":"Medium–High","soloQ":3,"swf":5,"unlockPriority":"Medium–High","glossaryKeys":["tunneling","anti-tunnel","hook-state","trade","swf","solo-q"],"useCases":["Pull a tunneled teammate away from immediate elimination.","Spread Hook States across the team so the Killer needs more total hooks to secure a kill.","Protect a weaker teammate or a teammate carrying key endgame value."],"counters":["Using it at the wrong time can simply make you the new tunnel target.","The live cost leaves you Injured and Broken for 160/140/120 seconds.","It gives little value when the Killer is already spreading hooks evenly.","One poorly timed use consumes the perk for the rest of the Trial."],"pros":["Directly manipulates Hook State economy, something very few perks can do.","Can erase a large portion of a tunneling strategy with one rescue.","Becomes especially difficult for the Killer to plan around in coordinated teams."],"cons":["Requires strong timing and an accurate read of who actually needs the Hook State transfer.","Transfers danger rather than deleting it, so the user must be ready to survive the next chase."],"analysis":["Shoulder the Burden remains one of the strongest ways to attack tunneling because it changes Hook State economy directly. One use can pull a teammate back from Death Hook and transfer that danger onto a Survivor with more room to spare.","The live 10.2 cost is severe: the user becomes Injured and Broken for 160/140/120 seconds. That creates real healing and chase consequences after the trade.","Each Survivor can still use their own copy once per Trial, preserving a very high coordinated-team ceiling even though an individual use is substantially more dangerous than before.","That split explains the queue ratings: hook-state redistribution remains exceptional in coordinated teams, while Solo Q has a harder time identifying the right target and timing the transfer safely."],"verdict":"Still elite anti-tunnel utility, now with a much more painful personal cost. Crucially, 10.2 still allows multiple teammates to use their own copy during the Trial.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"tags":["Hook Economy","Team"],"queueRatingStatus":"reviewed","rankRange":[8,16],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"strong-inference","acquisition":{"type":"character","sourceCharacter":"Taurie Cain"},"synergyPerkIds":["will-to-live","deliverance","dead-hard","reassurance"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Will to Live","Deliverance","Dead Hard","Reassurance"],"antiSynergies":[],"name":"Shoulder the Burden","alternateName":null,"source":"Taurie Cain","status":"Live 10.2.0","currentEffect":"Once per Trial, while you have fewer than 2 Hook States and are next to a hooked Survivor, use Active Ability Button 2 to unhook them. They lose 1 Hook State; you gain 1 Hook State, scream, become Injured, and become Broken for 160/140/120 seconds.","activation":["Once per Trial, have fewer than 2 Hook States.","Stand next to a hooked Survivor and use Active Ability Button 2 to unhook them.","Ends/deactivates when: After use, the perk cannot be used again by that Survivor during the Trial.","Ends/deactivates when: Broken ends after 160/140/120 seconds."],"patchNote":"Latest live balance change (10.2.0): Replaced the Exposed (60/50/40 s) downside with becoming Injured and Broken for 160/140/120 seconds; the PTB's deactivation for all other Survivors did not ship.","plainEnglishSummary":"Once per Trial, transfer one Hook State from a hooked teammate to yourself, becoming injured and temporarily Broken.","cooldown":null,"duration":["Broken: 160/140/120 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Once per Trial for the perk user; cannot be used if you already have 2 Hook States.","statusEffectsInvolved":["Broken"],"specialInteractions":["The unhooked Survivor loses 1 Hook State and the perk user gains 1 Hook State.","The PTB-wide deactivation for all other Survivors was removed before the final live release."],"sourceCharacter":"Taurie Cain","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"off-the-record","rank":12,"tier":"A","roles":["Anti-Tunnel","Stealth"],"summary":"After an unhook, gain a 30/35/40-second anti-tunnel package: Aura protection, quieter Grunts of Pain, no Scratch Marks while sprinting, and Endurance.","metaStatus":"Strong","skillLevel":"Low–Medium","soloQ":5,"swf":4,"unlockPriority":"Very High","glossaryKeys":["anti-tunnel","tunneling","endurance","aura-reading","conspicuous-action"],"useCases":["Survive the dangerous window immediately after an unhook when the Killer returns to pressure the rescue.","Break tracking by denying Aura reads, Grunts of Pain, and sprinting Scratch Marks during the active window.","Use the Endurance layer to reach a safer structure or force the Killer to spend extra time securing the next down."],"counters":["The active window is only 30/35/40 seconds, so the Killer can delay a hard commitment.","Performing a Conspicuous Action ends the Endurance portion early.","The perk only matters after an unhook, so it contributes nothing before your first hook state.","Basekit post-unhook Elusive overlaps part of this perk's tracking-denial value during the first 10 seconds after rescue."],"pros":["Combines several forms of post-unhook protection in one perk slot.","Works without communication and is therefore especially reliable in Solo Q.","Forces the Killer to solve both tracking and hit-protection problems if they immediately recommit."],"cons":["Its value is concentrated in the post-unhook window.","A patient Killer can sometimes wait out the timer or change targets.","Some of its protection overlaps with other anti-tunnel perks, so stacking too many can reduce build flexibility."],"analysis":["Off the Record takes this position because the moments immediately after an unhook are among the most strategically dangerous in Survivor. A Killer who converts that rescue into another fast down can accelerate the match toward a 3v1, and Off the Record attacks that conversion from several angles at once rather than relying on a single effect.","The tracking denial matters almost as much as the Endurance. Blocking Aura reads, suppressing Grunts of Pain, and removing sprinting Scratch Marks make it harder for the Killer to simply reacquire the rescued Survivor through information. On indoor maps or around line-of-sight breaks, that can turn what would have been a straightforward tunnel into a genuine search problem.","The Endurance layer then gives the perk a direct fail-safe if the Killer does find you. Unlike Will to Live, it does not require a pickup and Skill Check, but the protection is shorter-lived and can be cut down by a Conspicuous Action. That makes Off the Record less dominant than the very top anti-tunnel options, but also easier to benefit from in ordinary play.","Its best quality is self-sufficiency. Solo Q players do not need teammates to understand the plan, and SWF teams can deliberately route the protected Survivor toward safer areas while the rest of the team converts the Killer's lost time into generators. The perk is not universal because it does nothing before a hook, but once a match becomes tunnel-heavy it can be one of the highest-impact slots in the build."],"verdict":"A premium post-unhook insurance perk. Off the Record is strongest when the Killer tries to immediately convert a rescue into another down, because it attacks tracking and hit protection at the same time.","publicationStatus":"published","tags":["Information Denial"],"queueRatingStatus":"reviewed","rankRange":[12,17],"rankConfidence":"Medium","rankStatus":"mechanics-flag","evidenceStatus":"mechanics-verified-later","acquisition":{"type":"character","sourceCharacter":"Zarina Kassir"},"synergyPerkIds":["resurgence","will-to-live","iron-will","made-for-this"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Resurgence","Will to Live","Iron Will","Made for This"],"antiSynergies":[],"name":"Off the Record","alternateName":null,"source":"Zarina Kassir","status":"Live 10.2.0","currentEffect":"After you are unhooked or unhook yourself, Off the Record activates for 30/35/40 seconds. While active, it blocks your Aura from being revealed, suppresses your Grunts of Pain while Injured, prevents you from leaving Scratch Marks while sprinting, and grants Endurance. Endurance ends early if you perform a Conspicuous Action. Powering the Exit Gates alone does not deactivate the perk.","activation":["Be unhooked by another Survivor or unhook yourself.","Ends/deactivates when: The 30/35/40-second activation timer expires.","Ends/deactivates when: Endurance ends early if you perform a Conspicuous Action; the Aura protection, Grunt suppression, and Scratch Mark suppression otherwise follow the activation timer.","Ends/deactivates when: Powering the Exit Gates alone does not deactivate the perk in the current live version."],"patchNote":"Latest live balance change (9.2.2): Re-added Endurance and shortened the duration to 30/35/40 seconds from 60/70/80 seconds.","plainEnglishSummary":"After you leave a hook, you gain 30/35/40 seconds of Aura protection, quieter pain grunts while injured, no Scratch Marks while sprinting, and Endurance; a Conspicuous Action ends Endurance early, while powering the Exit Gates alone does not end the perk.","cooldown":null,"duration":["Off the Record: 30/35/40 seconds by tier.","Endurance: until its normal duration/effect ends, or earlier when you perform a Conspicuous Action."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Can activate on an unhook; no once-per-Trial limit is specified in the official effect history.","statusEffectsInvolved":["Endurance"],"specialInteractions":["Performing a Conspicuous Action cancels Endurance early but does not end the other timed effects.","The Exit Gates being powered does not disable the perk in the current live version."],"sourceCharacter":"Zarina Kassir","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"deliverance","rank":13,"tier":"A","roles":["Rescue","Endgame"],"summary":"After a safe rescue, your first-stage self-unhook is guaranteed once, at the cost of a long Broken period.","metaStatus":"Strong","skillLevel":"Medium","soloQ":3,"swf":5,"unlockPriority":"High","glossaryKeys":["hook-state","broken","trade","solo-q","swf"],"useCases":["Remove the need for a teammate to rotate across the map for your rescue.","Take an intentionally awkward chase or basement hook after the perk is armed.","Create powerful endgame Hook Trades because you can rescue someone and then free yourself."],"counters":["If the Killer finds and hooks you before you get a safe rescue, the perk does nothing.","A failed or unsafe rescue does not arm it.","The 120-second Tier III Broken duration makes the post-unhook reset much slower than before 10.1.","Second Hook Stage and last-Survivor situations disable its self-rescue value."],"pros":["Once armed, it gives you rescue independence with no teammate travel time.","Can make otherwise terrible hook locations strategically acceptable.","Has unusually high endgame leverage when trading for a teammate."],"cons":["The famous first-chase problem is real: early pressure can delete the perk before it activates.","Requires altruistic setup before it becomes useful.","The 10.1 Broken-duration nerf significantly delays healing after the self-unhook."],"analysis":["Deliverance creates value by deleting an entire rescue rotation. Once it is armed, the team knows that your first hook does not automatically require another Survivor to abandon a generator, cross the map, and expose themselves near the hook. That is a large tempo swing, especially late in a match when every few seconds on the final generators matter.","The price is reliability. If you are the first Survivor found and hooked, Deliverance is a dead perk slot. That makes positioning and early-match awareness part of the skill requirement even though the self-unhook itself is automatic. SWF can deliberately route the Deliverance user away from the first chase; Solo Q cannot guarantee that.","The 10.1.0 nerf matters. Tier III now leaves you Broken for 120 seconds instead of the much shorter historical duration, so Deliverance is no longer a clean self-rescue followed by an immediate reset. The perk is strongest when the time saved by not requiring a rescuer matters more than the delayed heal, which is often true in late game, split-pressure situations, and coordinated teams.","Shoulder the Burden can interact with Deliverance by changing Hook-State distribution, but both perks now carry major strategic costs. Even without that interaction, a guaranteed self-rescue remains unique enough to keep Deliverance a premium rescue perk."],"verdict":"Still a premium rescue perk after the 10.1 Broken nerf. The setup can fail, but once armed Deliverance changes the team’s rescue economy and can produce game-winning endgame trades.","publicationStatus":"published","tags":["Unhooking","Self-Rescue"],"queueRatingStatus":"reviewed","rankRange":[10,18],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Adam Francis"},"synergyPerkIds":["will-to-live","shoulder-the-burden","off-the-record","kindred"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"synergies":["Will to Live","Shoulder the Burden","Off the Record","Kindred"],"antiSynergies":[],"name":"Deliverance","alternateName":null,"source":"Adam Francis","status":"Live 10.2.0","currentEffect":"After safely unhooking another Survivor, your next self-unhook attempt during the first Hook Stage succeeds. Afterward you suffer Broken for 160/140/120 seconds. Cannot activate if you are in the second Hook Stage or were hooked while the last Survivor remaining.","activation":["Safely unhook another Survivor.","Be hooked in the first Hook Stage and attempt to self-unhook.","Ends/deactivates when: Cannot activate after reaching the second Hook Stage or if hooked while last remaining."],"patchNote":"Latest live balance change (10.1.0): Changed post-self-unhook Broken duration to 160/140/120 seconds.","plainEnglishSummary":"A safe unhook lets you guarantee a self-unhook during your first Hook Stage, followed by Broken.","cooldown":null,"duration":["Broken: 160/140/120 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Once per Trial; deactivates after successful self-unhook.","statusEffectsInvolved":["Broken"],"specialInteractions":["A safe rescue means the rescued Survivor avoids a subsequent hit within the safe-unhook evaluation window."],"sourceCharacter":"Adam Francis","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"five-moves-ahead","rank":14,"tier":"A","roles":["Chase","Pallet","Information"],"summary":"During chase or Terror Radius pressure, see the five closest Pallets and begin moving 50% earlier after dropping one, with a cooldown after each drop.","metaStatus":"Strong","skillLevel":"Medium","soloQ":4,"swf":4,"unlockPriority":"Very High","glossaryKeys":["looping","terror-radius","aura-reading","pre-drop","greed"],"useCases":["Route toward remaining resources once a chase starts.","Make pallet drops safer against ranged and zoning Killers.","Create extra distance after a stun or forced pallet break."],"counters":["Dropping a pallet starts a 40/35/30-second cooldown.","The aura information is unavailable outside chase and the Killer's Terror Radius.","Killers such as The Nurse can reduce the value of pallet-focused routing."],"pros":["Combines chase information with a real pallet-interaction advantage.","Particularly strong for experienced players who already know window locations.","Useful against a very wide range of Killers."],"cons":["Less beginner-friendly than current Windows of Opportunity.","Cooldown can remove the information immediately after a pallet is used."],"analysis":["Five Moves Ahead became the dedicated Pallet counterpart to the reworked Windows of Opportunity. It now shows only the five closest Pallets, but still provides the powerful 50% earlier movement after a Pallet drop.","That earlier movement can materially change whether the Killer catches you during the post-drop recovery window, especially against ranged or anti-loop powers where every fraction of a second matters.","Losing Window information narrows the perk considerably. It is excellent at answering the question “where is my next Pallet?” and no longer tries to solve the whole tile for you.","The result is a strong chase specialist rather than broad map information. Its old placement needs review because the 10.2 version has a clearer job and a smaller information footprint."],"verdict":"A focused Pallet-routing and Pallet-recovery perk after 10.2. Stronger at its specific job, narrower as an all-purpose chase map.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"tags":[],"queueRatingStatus":"reviewed","rankRange":[12,20],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"strong-inference","acquisition":{"type":"character","sourceCharacter":"Kwon Tae-Young"},"synergyPerkIds":["lithe","finesse","resilience","dead-hard"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Lithe","Finesse","Resilience","Dead Hard"],"antiSynergies":[],"name":"Five Moves Ahead","alternateName":null,"source":"Kwon Tae-Young","status":"Live 10.2.0","currentEffect":"While you are inside the Killer's Terror Radius or being chased by the Killer, you see the Auras of the 5 closest Pallets. After you drop a Pallet, you start moving 50% earlier. Dropping a Pallet puts the perk on a 40/35/30-second cooldown.","activation":["Be inside the Killer's Terror Radius or be chased by the Killer to see the 5 closest Pallets and receive the Pallet-drop movement benefit.","Ends/deactivates when: The Aura and movement effects are unavailable while the perk is on its 40/35/30-second cooldown.","Ends/deactivates when: Outside the Killer's Terror Radius and chase, the active effects are unavailable."],"patchNote":"Latest live balance change (10.2.0): Specialized the perk to Pallets only and clarified the Pallet-drop benefit as starting movement 50% earlier; cooldown remains 40/35/30 seconds.","plainEnglishSummary":"In danger, see the five nearest Pallets; dropping one lets you resume movement earlier and then starts a tiered cooldown.","cooldown":"40/35/30 seconds after dropping a Pallet.","duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The Aura effect now tracks only Pallets, not Windows.","The 50% value means you start moving earlier after the Pallet drop; it is not a generic 50% Pallet-drop interaction-speed bonus."],"sourceCharacter":"Kwon Tae-Young","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"kindred","rank":15,"tier":"A","roles":["Information","Rescue"],"summary":"Turns hook events into team-wide positioning information and shows the Killer near the hook.","metaStatus":"Strong","skillLevel":"Low","soloQ":5,"swf":2,"unlockPriority":"High","glossaryKeys":["aura-reading","solo-q","swf","terror-radius","hook-state"],"useCases":["Know whether somebody else is already rotating for the rescue so you can stay on your generator.","See whether the Killer is lingering near the hook before committing to a save.","Read teammate rotations when another Survivor is hooked in Solo Q."],"counters":["Voice comms can reproduce much of the teammate-position information in a coordinated SWF.","The perk provides information but cannot force random teammates to make the correct decision.","The Killer-aura portion is limited to the hook area."],"pros":["Excellent Solo Q coordination without requiring any setup.","General perk, so there is no character unlock investment.","Useful whether you are the hooked Survivor or somebody deciding how to react to a hook."],"cons":["Much less unique in a four-person team with strong comms.","No direct chase or repair-speed benefit.","Value appears around hook events rather than continuously."],"analysis":["Kindred attacks one of Solo Q’s biggest sources of lost time: duplicated or absent rescue rotations. When a teammate is hooked, knowing that another Survivor is already moving toward the rescue lets you keep repairing instead of becoming the second or third person walking toward the same hook.","It is equally useful when you are the hooked Survivor because your teammates can see one another. That makes it easier for the team to identify who should stay on a generator, who is in chase, and who is positioned to rescue. The nearby Killer aura adds another layer by exposing obvious camping or immediate hook pressure.","Otz explicitly treated Kindred as somewhat artificially high in his 9.5 list because it fills knowledge gaps that newer and Solo Q players struggle with. We agree with that philosophy, but not because the perk is secretly weak. Match information has real tempo value when it prevents three people from abandoning generators for the same rescue."],"verdict":"Outstanding overall and exceptional comfort in Solo Q. It is simple, reliable, and one of the best ways to stop random-team hook rotations from turning into wasted minutes.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"tags":["Info","Unhooking","Solo Q"],"queueRatingStatus":"reviewed","rankRange":[10,22],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["open-handed","well-make-it","reassurance","deliverance"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Open-Handed","We'll Make It","Reassurance","Deliverance"],"antiSynergies":[],"name":"Kindred","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"While you are hooked, all Survivors see each other's Auras, and while the Killer is within 14/15/16 metres of your Hook, all Survivors see the Killer's Aura. While another Survivor is hooked, you see the Auras of the other Survivors, and while the Killer is within 14/15/16 metres of that hooked Survivor, you see the Killer's Aura.","activation":["Any Survivor is hooked.","Ends/deactivates when: The effect ends when no Survivor remains hooked."],"patchNote":"Latest live balance change (10.2.0): Increased Killer Aura reveal radius around a Hook from 8/12/16 metres to 14/15/16 metres; Survivor Aura-sharing behavior is unchanged.","plainEnglishSummary":"Hook events share teammate Auras and reveal the Killer near the Hook, with the Killer-reveal radius now 14/15/16 metres.","cooldown":null,"duration":["While a Survivor is hooked."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["When the perk owner is hooked, the other Survivors see one another's Auras; when another Survivor is hooked, the perk owner sees all other Survivors' Auras."],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"well-make-it","rank":16,"tier":"A","roles":["Healing","Rescue","Objective"],"summary":"After an unhook, heal other Survivors at double speed for up to 90 seconds.","metaStatus":"Strong","skillLevel":"Low","soloQ":4,"swf":4,"unlockPriority":"Immediate","glossaryKeys":["reset","hook-state","pressure"],"useCases":["Heal the Survivor you just rescued before the Killer can return and interrupt the reset.","Carry the 90-second healing bonus away from hook to rapidly stabilize another injured teammate.","Reduce the time two Survivors spend off generators during routine post-hook resets."],"counters":["The perk must be activated by unhooking another Survivor.","A Killer returning immediately to hook can deny a safe healing window despite the speed bonus.","Broken, Plague-style anti-healing, or teams intentionally staying injured can reduce its value."],"pros":["Extremely simple trigger tied to an action Survivors already need to perform.","A 90-second Tier III window is long enough to heal more than only the rescued teammate.","Strong in both Solo Q and SWF with almost no mechanical execution requirement."],"cons":["Offers no value before you perform an unhook.","Does not protect the healed Survivor if the Killer immediately commits to tunneling.","Healing speed is less valuable in matchups where healing itself is strategically inefficient."],"analysis":["We'll Make It closes the top twenty because it is one of the cleanest tempo perks in Survivor's entire roster. Unhooking is already mandatory team work. The perk simply turns that necessary action into a long window where healing other Survivors takes half the usual time.","The obvious use is the under-hook reset. A normal heal asks two Survivors to stop progressing the match for a meaningful amount of time; doubling the healing speed gets both players back to useful jobs much sooner. That value is especially visible when the Killer has moved away and the team can safely cash in the heal immediately.","The 90-second duration is what keeps the perk from being merely a hook-heal gimmick. After the rescue, the user can rotate into another injured teammate and still carry the bonus. In messy Solo Q matches, that long window makes the perk forgiving because the user does not need perfect communication or timing to get a second useful heal.","It ranks below Resurgence because it needs the user to be the rescuer and still requires the full heal interaction, while Resurgence front-loads most of the heal automatically for the unhooked Survivor. It also lacks the protection of Babysitter or anti-tunnel perks. But for raw, repeatable team efficiency, We'll Make It remains excellent."],"verdict":"Simple, reliable, and brutally efficient. We'll Make It is one of the best general-purpose healing perks because its trigger is normal gameplay and its 90-second payoff is difficult to waste.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"tags":["Efficiency"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["resurgence","babysitter","botany-knowledge","kindred"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Resurgence","Babysitter","Botany Knowledge","Kindred"],"antiSynergies":[],"name":"We'll Make It","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"Whenever you unhook a Survivor, for 70/80/90 seconds you heal other Survivors 100% faster.","activation":["Unhook another Survivor.","Ends/deactivates when: The effect ends after 70/80/90 seconds."],"patchNote":"Latest live balance change (10.2.0): Increased activation duration from 30/60/90 to 70/80/90 seconds; +100% altruistic healing speed remains.","plainEnglishSummary":"After an unhook, you heal other Survivors twice as fast for 70/80/90 seconds.","cooldown":null,"duration":["70/80/90 seconds after unhooking another Survivor."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The 100% speed bonus applies to Altruistic Healing, not self-healing."],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"deja-vu","rank":17,"tier":"A","roles":["Information","Objective"],"summary":"Highlights the three closest clustered generators and gives you a repair bonus on those generators.","metaStatus":"Strong","skillLevel":"Low","soloQ":5,"swf":4,"unlockPriority":"Medium–High","glossaryKeys":["3-gen","pressure","solo-q","aura-reading"],"useCases":["Break dangerous generator clusters before they become an endgame 3-gen.","Find objectives quickly on indoor or unfamiliar maps.","Spend less rotation time searching and more time actually repairing."],"counters":["The repair bonus is modest and only applies to the highlighted generators.","A highlighted generator may be unsafe or temporarily blocked, so blindly following the perk can be inefficient.","Experienced coordinated teams already know generator spawns and can reproduce much of the routing value."],"pros":["Combines objective information and a permanent repair-speed bonus in one General perk.","Directly teaches good generator macro by pointing at the cluster most worth breaking.","Always available and especially helpful on indoor maps."],"cons":["Does not help during chase or rescues.","The 6% Tier III repair bonus is useful rather than spectacular.","Its information component becomes less necessary as map knowledge improves."],"analysis":["Déjà Vu is a deceptively strong macro perk because it solves two problems at once. First, it removes time spent wandering for a generator. Second, it identifies the three generators whose proximity is most dangerous if left until late game. Working that cluster naturally spreads the remaining objectives farther apart.","The 6% Tier III repair bonus is not the main reason it ranks this high, but it is meaningful because it applies to the exact generators the perk is already encouraging you to prioritize. The information and speed components reinforce the same decision instead of pulling your build in two directions.","Like Kindred and Windows, some of Déjà Vu’s strength is learning value. A highly experienced SWF that knows generator spawn logic and communicates rotations gains less from the aura information. A returning or Solo Q player gains much more because the perk removes map-search time and provides a clear objective whenever the match feels directionless.","We rank it this position rather than above the chase and hook-economy perks because generator knowledge can eventually be internalized and the speed bonus is modest. But as a free General perk with no setup, no cooldown, and almost no bad-match scenario, it is one of the safest high-value slots in the game."],"verdict":"An outstanding default perk, especially in Solo Q or while relearning maps. It is reliable and quietly prevents some of the worst generator layouts Survivors create for themselves.","publicationStatus":"published","tags":["Info","Gen","Anti-3-gen"],"queueRatingStatus":"reviewed","rankRange":[13,22],"rankConfidence":"Low","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["prove-thyself","hyperfocus"],"synergyOther":["Toolboxes"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Prove Thyself","Hyperfocus","Toolboxes"],"antiSynergies":[],"name":"Déjà Vu","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"The Auras of the three closest Generators that are grouped together are revealed to you. You repair those Generators 4/5/6% faster.","activation":["Ends/deactivates when: Highlighted Generators update as the closest grouped trio changes."],"patchNote":"Latest live balance change (9.1.0): Removed tracking of highlighted Generators by Maps.","plainEnglishSummary":"It highlights a nearby cluster of three Generators and speeds repairs on them.","cooldown":null,"duration":["Aura highlights and repair bonus are available throughout the Trial."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Maps no longer track the Generators revealed by this perk."],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"iron-will","rank":18,"tier":"A","roles":["Chase","Stealth"],"summary":"While injured and not Exhausted, your Grunts of Pain are completely silent at Tier III.","metaStatus":"Strong","skillLevel":"Medium–High","soloQ":5,"swf":4,"unlockPriority":"Very High","glossaryKeys":["exhausted","health-state","looping"],"useCases":["Break line-of-sight during chase and deny the Killer the audio cue they use to track your next route.","Hide or reposition while injured without giving away your exact location through pain sounds.","Make indoor and high-wall tiles harder for the Killer to read when visual information is limited."],"counters":["Iron Will does not function while you are Exhausted.","Scratch Marks, Pools of Blood, Aura reading, and direct sight can still reveal you.","Its value is lower against Killers or situations where audio tracking is not important."],"pros":["Removes an important tracking channel without requiring a cooldown or manual activation.","Gets stronger on complex tiles where Killers rely heavily on sound through walls.","Excellent Solo Q value because it requires no teammate coordination."],"cons":["Temporarily disabled by Exhaustion, creating awkward anti-synergy with several popular chase perks.","Provides little benefit while Healthy.","Does not hide the other tracking evidence an injured Survivor leaves behind."],"analysis":["Iron Will sits at this position because information denial is strongest when it removes something the Killer normally receives for free. Injured Survivors are loud, and experienced Killers use those sounds constantly to resolve mindgames at walls, jungle gyms, indoor rooms, and other places where they briefly lose visual contact.","At Tier III, removing those Grunts of Pain can turn a predictable chase into a genuine guessing game. The Survivor can double back, hold a corner, leave a tile, or change elevation without announcing the decision through audio. The perk does not create distance directly, but it can force the Killer to spend extra seconds confirming where the Survivor went, which often matters just as much.","The major constraint is Exhaustion. Iron Will stops functioning while Exhausted, so Sprint Burst or Lithe users may lose the perk exactly during the early part of a chase. Dead Hard is a cleaner partner because the Survivor often remains non-Exhausted until the moment the perk is actually used. This interaction means Iron Will rewards deliberate build construction rather than fitting equally well everywhere.","Its value also rises with player experience. A Survivor who keeps running in a straight visible path gains little from silence. A Survivor who understands line-of-sight breaks, checkspots, and pathing can use the missing audio cue to manufacture mistakes from the Killer."],"verdict":"Powerful chase stealth with a real skill ceiling. Iron Will is at its best when you deliberately exploit missing audio information, not when you simply expect silence to make you invisible.","publicationStatus":"published","tags":["Information Denial"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Jake Park"},"synergyPerkIds":["dead-hard","resilience","lucky-break","quick-quiet"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Dead Hard","Resilience","Lucky Break","Quick & Quiet"],"antiSynergies":[],"name":"Iron Will","alternateName":null,"source":"Jake Park","status":"Live 10.2.0","currentEffect":"While Injured, reduce the volume of your Grunts of Pain by 80/90/100%. Iron Will does not function while you are Exhausted, but it does not itself inflict Exhausted.","activation":["Be in the Injured State.","Not be suffering from Exhausted.","Ends/deactivates when: The effect stops when you are no longer Injured or become Exhausted."],"patchNote":"Latest live balance change (8.1.0): Increased Grunts of Pain volume reduction from 25/50/75% to 80/90/100%.","plainEnglishSummary":"While Injured and not Exhausted, it greatly reduces the volume of your Grunts of Pain.","cooldown":null,"duration":["No fixed duration; applies while the activation conditions are met."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Exhausted (prevents effect; Iron Will does not inflict it)"],"specialInteractions":[],"sourceCharacter":"Jake Park","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"plot-twist","rank":19,"tier":"A","roles":["Healing","Anti-Slug","Utility"],"summary":"While injured, down yourself silently and recover 25% faster to stand up Healthy with a brief Haste burst; it can return once in endgame.","metaStatus":"Strong","skillLevel":"Medium","soloQ":4,"swf":5,"unlockPriority":"High","glossaryKeys":["dying-state","anti-slug","haste","health-state","snowball"],"useCases":["Convert an injury into a full self-heal without a teammate or Med-Kit.","Force the Killer into an awkward pickup-or-leave decision when they need to pressure elsewhere.","Use a controlled down to position beneath a pallet or manipulate endgame timing."],"counters":["Using it where the Killer can immediately reach you turns the perk into a free pickup.","The self-recovery takes long enough that aura reading or good Killer awareness can interrupt it.","After recovering from the Dying State by any means, it is disabled until the Exit Gates are powered.","Hex: Under Your Thumb can cap running Haste while the Hex remains lit."],"pros":["Provides a self-heal that ignores ordinary healing-speed penalties.","Can create deliberate anti-slug and pickup dilemmas.","Offers a second activation once the Exit Gates are powered."],"cons":["Requires safe timing and positioning.","Temporarily puts you in the Dying State by choice.","Licensed unlock and less plug-and-play than Lithe."],"analysis":["Plot Twist is one of the strangest strong perks in the game because voluntarily entering the Dying State sounds like a drawback until you look at the decisions it creates. Used safely, it is a full self-heal with 25% faster recovery and a Haste burst at the end.","The more advanced value is strategic. If the Killer needs to leave you to stop a generator or chase another Survivor, Plot Twist threatens to return you to Healthy without consuming a teammate's time. If they pick you up instead, anti-tunnel or pickup-denial tools can punish that choice. The perk can therefore manufacture lose-lose decisions rather than simply save healing time.","It also has unusual endgame utility because the ability can return when the Exit Gates are powered. Controlled downs can slow the Endgame Collapse, position you for pallet interactions, or let you recover safely while the Killer is forced to defend another objective.","The downside is that bad Plot Twist use is genuinely bad. Dropping in line of sight, under active aura reading, or without enough distance simply hands the Killer a down. Its ceiling is high, but Lithe ranks above it because Lithe's value is dramatically easier to realize in ordinary matches."],"verdict":"Flexible utility with a surprisingly high ceiling. Plot Twist is both a self-reset and a decision-making weapon, but it rewards game sense far more than autopilot use.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Nicolas Cage"},"synergyPerkIds":["will-to-live","tenacity","flip-flop","power-struggle"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Will to Live","Tenacity","Flip-Flop","Power Struggle"],"antiSynergies":[],"name":"Plot Twist","alternateName":null,"source":"Nicolas Cage","status":"Live 10.2.0","currentEffect":"Whenever you are Injured, Plot Twist is available. While crouching and stationary, press Active Ability to silently enter the Dying State, suppressing your Grunts of Pain and Pools of Blood and unlocking full self-recovery at 25% faster Recovery speed. After you fully recover from the Dying State using Plot Twist, you instantly become Healthy and gain 50% Haste for 2/3/4 seconds by tier. After recovering from the Dying State by any means, the perk is disabled until the Exit Gates are powered, when it can reactivate one more time.","activation":["Be in the Injured State.","Crouch and remain stationary, then press Active Ability.","Ends/deactivates when: The activation ends when you recover from the Dying State or are otherwise interrupted/leave the state.","Ends/deactivates when: After recovery from the Dying State by any means, the perk is disabled until the Exit Gates are powered, when it can reactivate once more."],"patchNote":"Latest live balance change (9.2.0): Added a 25% Recovery-speed bonus while recovering from the Dying State using Plot Twist.","plainEnglishSummary":"While injured, you can silently down yourself and recover to full health, gaining a short Haste burst, with a second use after the Exit Gates are powered.","cooldown":null,"duration":["Recovery speed bonus: while recovering from the Dying State caused by Plot Twist.","Haste: 50% for 2/3/4 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"One activation before Exit Gates are powered; after recovery the perk can reactivate once when the Exit Gates are powered, for up to two uses in the Trial.","statusEffectsInvolved":["Haste"],"specialInteractions":["The silent entry into the Dying State suppresses Grunts of Pain and Pools of Blood; the recovery speed bonus is 25%."],"sourceCharacter":"Nicolas Cage","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"were-gonna-live-forever","rank":20,"tier":"A","roles":["Anti-Slug","Healing","Team Support"],"summary":"Heal downed teammates 100% faster and give them brief Endurance when you pick them back up.","metaStatus":"Strong","skillLevel":"Medium","soloQ":4,"swf":5,"unlockPriority":"Very High","glossaryKeys":["slugging","anti-slug","dying-state","endurance","snowball"],"useCases":["Break a Killer's multi-Survivor slug snowball before they can convert every down into hooks.","Swoop in after the Killer leaves a downed teammate and complete the pickup quickly.","Protect a freshly recovered teammate from being immediately downed again."],"counters":["A Killer who hooks every down immediately can deny most of the perk's value.","The Endurance grant can trigger only once every 30 seconds.","Reaching the downed Survivor safely is still required."],"pros":["Cuts one of the riskiest Survivor recovery interactions in half.","Adds Endurance after the pickup, not just speed.","Directly punishes Killers who overextend for slug pressure."],"cons":["Can be a dead slot against immediate-hook play.","More reliable with communication or good teammate-location information.","Its best moments depend on another Survivor already being downed."],"analysis":["We're Gonna Live Forever makes this position because slugging pressure can end a match before normal healing perks have time to matter. Doubling the speed of a Dying-State heal lets one Survivor reverse a down while the Killer is carrying, chasing, or trying to extend the snowball elsewhere.","The Endurance component is what turns the perk from simple speed into genuine anti-slug insurance. A teammate who stands up and can immediately absorb another qualifying hit is much harder for the Killer to erase again, especially when the pickup happens during a chaotic endgame or multi-down situation.","Its ceiling rises substantially in coordinated teams because teammates can deliberately recover, communicate Killer position, and create a safe pickup window. In Solo Q, the perk still works, but finding and reaching the right downed teammate at the correct moment is less predictable.","The reason it finishes below Plot Twist is independence. Plot Twist creates its own value and can heal the user without relying on Killer behavior. WGLF needs somebody else to be slugged. When that condition appears, however, it is one of the most efficient ways to stop a Killer snowball."],"verdict":"Strong anti-slug support. It will not fire in every match, but when a Killer starts chaining downs, the pickup speed plus Endurance can turn a collapse back into a playable game.","publicationStatus":"published","tags":["Teamplay"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"David King"},"synergyPerkIds":["made-for-this","botany-knowledge","for-the-people","bond"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Made for This","Botany Knowledge","For the People","Bond"],"antiSynergies":[],"name":"We're Gonna Live Forever","alternateName":null,"source":"David King","status":"Live 10.2.0","currentEffect":"When healing a Dying Survivor, your Healing speed is increased by 100%. A Survivor you heal from Dying to Injured gains Endurance for 6/8/10 seconds. The Endurance effect can trigger only once every 30 seconds.","activation":["Heal a Survivor in the Dying State for the 100% healing-speed bonus.","Heal a Dying Survivor back to Injured to grant them Endurance.","Ends/deactivates when: Endurance ends after 6/8/10 seconds, subject to Endurance rules.","Ends/deactivates when: The Endurance grant is unavailable during its 30-second cooldown."],"patchNote":"Latest live balance change (8.3.2): Reverted the healing-speed bonus to 100% (was 150% in 8.3.0); 8.3.0 replaced Tokens with a 6/8/10 s Endurance grant on a 30 s cooldown.","plainEnglishSummary":"Speeds up healing downed teammates and grants the teammate you get back up brief Endurance.","cooldown":"30 seconds between Endurance grants","duration":["Endurance: 6/8/10 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"The Endurance effect can trigger once every 30 seconds.","statusEffectsInvolved":["Endurance"],"specialInteractions":["The healing-speed bonus applies while healing a Dying Survivor; the Endurance grant occurs when that Survivor reaches Injured."],"sourceCharacter":"David King","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"babysitter","rank":21,"tier":"A","roles":["Anti-Tunnel","Rescue","Information"],"summary":"After you unhook someone, reveal the Killer for 8 seconds while the rescued Survivor gets 10% Haste and leaves no Scratch Marks or Blood for up to 30 seconds.","metaStatus":"Strong","skillLevel":"Low–Medium","soloQ":4,"swf":4,"unlockPriority":"Very High","glossaryKeys":["anti-tunnel","tunneling","haste","aura-reading","hook-state"],"useCases":["Make a tunneled rescue much harder to immediately reacquire.","Use the Killer Aura read to decide whether to heal, split, or run.","Give the rescued Survivor enough speed and trail denial to reach a safer tile."],"counters":["Only works when you perform the unhook.","The Haste does not itself prevent a down if the Killer maintains direct sight.","A Killer who leaves the hook may never test the anti-tunnel package.","Hex: Under Your Thumb can cap running Haste while the Hex remains lit.","Basekit post-unhook Elusive overlaps part of this perk's tracking-denial value during the first 10 seconds after rescue."],"pros":["Excellent rescue protection in one slot.","8 seconds of Killer Aura information helps both macro and safety.","The 30-second 10% Haste window is long enough to matter in a real chase."],"cons":["Hook-event dependent.","Does not protect you, only the rescued Survivor.","Less valuable when the Killer consistently rotates away."],"analysis":["Babysitter deserves much more respect because its current package is much stronger than its old reputation suggests. The rescued Survivor receives 10% Haste for as long as 30 seconds while also hiding Scratch Marks and Pools of Blood, which attacks both chase speed and tracking at once.","The eight-second Killer Aura read matters just as much. It tells the rescuer whether the Killer is returning, proxying nearby, or rotating elsewhere, so the team can choose between healing, splitting, or immediately leaving the area with much better information.","The perk scales well in both Solo Q and SWF. Solo players get a self-contained safety signal and a strong rescue buff, while coordinated teams can route the protected Survivor toward a preplanned tile or reset location.","It still sits below the very best anti-tunnel perks because the trigger belongs to the rescuer and the Killer can simply choose another target. But when the Killer does try to tunnel through the unhook, Babysitter creates an unusually strong 30-second problem for them."],"verdict":"A genuinely strong modern rescue perk. Babysitter combines speed, tracking denial, and Killer information into one of the best anti-tunnel support packages available.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":[18,30],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Steve Harrington"},"synergyPerkIds":["shoulder-the-burden","well-make-it","kindred","borrowed-time"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Shoulder the Burden","We'll Make It","Kindred","Borrowed Time"],"antiSynergies":[],"name":"Babysitter","alternateName":null,"source":"Steve Harrington","status":"Live 10.2.0","currentEffect":"When you unhook another Survivor, you see the Killer's Aura for 8 seconds. The rescued Survivor leaves no Scratch Marks or Pools of Blood and gains 10% Haste for 20/25/30 seconds.","activation":["Unhook another Survivor.","Ends/deactivates when: Aura reveal and rescued Survivor effects end after their durations."],"patchNote":"Latest live balance change (9.0.0): Reduced the rescued Survivor's Haste bonus to 10%.","plainEnglishSummary":"Unhooking a teammate briefly reveals the Killer and gives the rescued Survivor a temporary Haste and trail-suppression effect.","cooldown":null,"duration":["Killer Aura reveal: 8 seconds.","Rescued Survivor Haste and no Scratch Marks/Pools of Blood: 20/25/30 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste"],"specialInteractions":["The effects apply to the rescued Survivor; the Aura reveal applies to you."],"sourceCharacter":"Steve Harrington","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"botany-knowledge","rank":22,"tier":"A","roles":["Healing","Objective"],"summary":"Permanently heal 50% faster at Tier III, with no trigger, cooldown, or remaining Med-Kit efficiency penalty.","metaStatus":"Strong","skillLevel":"Low","soloQ":4,"swf":4,"unlockPriority":"Very High","glossaryKeys":["reset","health-state"],"useCases":["Shorten ordinary teammate heals so two Survivors return to generators or rescues sooner.","Improve emergency resets when the team has several injured Survivors but limited safe time.","Amplify self-heal or Med-Kit strategies without the old item-efficiency drawback."],"counters":["Broken still prevents completing a heal regardless of speed.","A Killer who immediately pressures the healing area can deny the time needed to finish.","Faster healing is less valuable in matches where the team deliberately stays injured."],"pros":["Always active and mechanically effortless.","50% is a large enough bonus to meaningfully change reset time.","Patch 9.0.0 removed the old Med-Kit efficiency penalty, restoring clean item synergy."],"cons":["Does not create value unless healing actually occurs.","Can tempt teams into over-healing instead of repairing when a reset is unnecessary.","Offers no direct chase protection or objective progress."],"analysis":["Botany Knowledge opens this band at this position because its current version is much cleaner than the perk many returning players remember. Tier III provides a permanent 50% healing-speed increase, and the 9.0.0 removal of the Med-Kit efficiency penalty eliminated the most awkward tradeoff from its previous design.","The practical value is team tempo. A heal normally occupies two Survivors at once: the injured player and the healer. Cutting that interaction substantially frees both players earlier, so the time saved is more meaningful than looking only at one progress bar. It is especially noticeable after unhooks, during multi-injury resets, and when the Killer temporarily loses map pressure.","The perk also has one of the healthiest reliability profiles in the healing category. It asks for no token, no hook trigger, no special location, and no successful Skill Check. If you heal another Survivor, it works. That simplicity makes it excellent in Solo Q, while coordinated teams can deliberately schedule very short resets around it.","Botany Knowledge stays outside the top thirty because healing itself is not always the correct macro decision. Against some Killers or in some game states, repairing while injured is stronger than resetting. The perk is therefore powerful whenever healing is strategically justified, but it cannot force healing to be the right play."],"verdict":"A top-tier pure healing-speed perk. Modern Botany Knowledge is simple, permanent, and efficient, but its value still depends on knowing when the team should actually stop to heal.","publicationStatus":"published","tags":["Efficiency","Reset"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Claudette Morel"},"synergyPerkIds":["well-make-it","resurgence","self-care"],"synergyOther":["Med-Kits"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["We'll Make It","Resurgence","Self-Care","Med-Kits"],"antiSynergies":[],"name":"Botany Knowledge","alternateName":null,"source":"Claudette Morel","status":"Live 10.2.0","currentEffect":"Increases your Healing speed by 30/40/50%.","activation":[],"patchNote":"Latest live balance change (9.0.0): Removed the Med-Kit efficiency penalty.","plainEnglishSummary":"You heal faster.","cooldown":null,"duration":["Continuous during the Trial."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The former Med-Kit efficiency penalty was removed in 9.0.0 and is not part of the live effect."],"sourceCharacter":"Claudette Morel","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"balanced-landing","rank":23,"tier":"A","roles":["Chase","Exhaustion","Mobility"],"summary":"Turn a fall into a 50% Haste burst, sharply reduce landing stagger, and silence landing noise.","metaStatus":"Strong","skillLevel":"Medium","soloQ":4,"swf":4,"unlockPriority":"High","glossaryKeys":["haste","exhausted","looping"],"useCases":["Convert elevated windows, hills, balconies, and map drops into immediate chase distance.","Use reduced stagger to make otherwise dangerous drops safe enough to extend a loop.","Force Killers to respect vertical escape routes that would normally cost the Survivor too much momentum."],"counters":["Requires usable elevation, making its value highly map- and tile-dependent.","Cannot activate while Exhausted and applies the normal Exhaustion timer after use.","Killers can sometimes zone Survivors away from the drop that would activate the perk.","Hex: Under Your Thumb can cap running Haste while the Hex remains lit."],"pros":["A full-strength Exhaustion burst with the added benefit of dramatically reduced landing stagger.","Can transform specific map structures into very strong chase resources.","Easy to understand mechanically once a valid drop is available."],"cons":["Some maps offer far fewer reliable activation points than others.","The user may be forced to path toward elevation instead of the objectively strongest tile.","Competes directly with more universally activatable Exhaustion perks."],"analysis":["Balanced Landing earns this position because its effect is powerful enough to reshape a chase whenever the map provides elevation. A 50% Haste burst for three seconds already matches the classic Exhaustion payoff, and the 75% reduction to landing stagger means the activation point itself preserves far more momentum than a normal drop.","That combination can make elevated structures disproportionately safe. A drop that would normally let the Killer recover the distance can instead become the moment the Survivor escapes the tile entirely. On maps with strong balconies, hills, stair structures, and drop windows, the Killer may need to route differently simply because Balanced Landing is possible.","The obvious weakness is map dependence. Sprint Burst works anywhere and Lithe only asks for a rushed vault; Balanced Landing needs geometry. Skilled players can memorize activation points and deliberately route toward them, but there will still be Trials where the relevant drops are awkward, unsafe, or nowhere near the chase.","That inconsistency keeps it below the most universal Exhaustion perks, but current usage shows it remains a serious option rather than a novelty. When the map cooperates, Balanced Landing can be one of the strongest chase perks in the entire loadout. When it does not, the slot can feel painfully quiet."],"verdict":"A real Exhaustion perk with a map-shaped ceiling. Balanced Landing can make vertical tiles oppressive for the Killer, but it cannot promise a good activation point every Trial.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Nea Karlsson"},"synergyPerkIds":["windows-of-opportunity","resilience","finesse","vigil"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Windows of Opportunity","Resilience","Finesse","Vigil"],"antiSynergies":[],"name":"Balanced Landing","alternateName":null,"source":"Nea Karlsson","status":"Live 10.2.0","currentEffect":"When you fall from a height, suppress landing noise, reduce fall stagger duration by 75%, and gain 50% Haste for 3 seconds. Cannot be used while Exhausted and causes Exhausted for 60/50/40 seconds.","activation":["Fall from a height.","You must not be Exhausted.","Ends/deactivates when: Haste ends after 3 seconds."],"patchNote":"Latest live balance change (3.4.0): No later material balance entry was found; 3.4.0 is the latest supportable material change in the available history.","plainEnglishSummary":"Falling from a height makes you land more quietly and grants a brief Haste burst.","cooldown":null,"duration":["Haste: 3 seconds.","Exhausted: 60/50/40 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste","Exhausted"],"specialInteractions":["Suppresses landing noise and reduces fall stagger duration."],"sourceCharacter":"Nea Karlsson","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"distortion","rank":24,"tier":"A","roles":["Stealth","Chase"],"summary":"Automatically block Killer Aura reads and hide Scratch Marks, then recharge tokens by spending time in chase.","metaStatus":"Strong","skillLevel":"Medium","soloQ":4,"swf":4,"unlockPriority":"High","glossaryKeys":["aura-reading","looping","pressure"],"useCases":["Deny common Aura-reading perks and add-ons that would otherwise reveal your position.","Use the Scratch-Mark suppression window to reposition after an attempted Aura read.","Recharge tokens through normal chase participation rather than hiding passively all match."],"counters":["It starts with only one Token and can hold only two.","Repeated Aura-reading effects can burn through tokens faster than you can recharge them.","It does not trigger while you are in the Dying State and does nothing against non-Aura tracking methods."],"pros":["Automatically protects against a large family of Killer information tools.","The modern recharge condition rewards taking chase instead of hiding near the Killer.","The Scratch-Mark suppression can turn a blocked Aura read into actual repositioning value."],"cons":["Match value depends heavily on whether the Killer brought Aura reading.","Limited tokens mean careless exposure to repeated reads can exhaust the perk quickly.","Can encourage overly passive play if the user values preserving tokens more than helping the team."],"analysis":["Distortion earns this position because Killer Aura reading is common enough that denying it can materially change positioning, especially at the start of a match and after hooks, generator kicks, or other information triggers. The perk's automatic activation also means the user does not need to identify exactly which Aura effect is being used before receiving protection.","The 9.5 recharge model improved the perk's strategic health. Regaining a Token after 15 seconds in chase means strong users can sustain the perk by participating in the dangerous part of Survivor gameplay rather than hiding in the Terror Radius. That gives Distortion a more active rhythm: block information, take chase, recharge, and be ready for the next read.","The additional Scratch-Mark suppression matters because blocking an Aura without changing position can still leave the Killer with enough tracking information to find you. A 12-second Tier III window can support a real rotation, line-of-sight break, or deceptive path if the user understands why the Aura read likely happened.","Its floor is matchup-dependent. Against a Killer build with little or no Aura reading, the slot may accomplish almost nothing. Even against heavy Aura builds, two maximum Tokens can disappear quickly. Distortion therefore ranks below universally active information perks, but in the matches where the Killer relies on Aura reads it can dismantle a meaningful part of their tracking plan."],"verdict":"A strong anti-information perk with a much healthier chase-based recharge loop. Distortion is not universal, but against Aura-heavy Killers it can erase some of their cleanest tracking windows.","publicationStatus":"published","tags":["Information Denial"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Jeff Johansen"},"synergyPerkIds":["iron-will","lucky-break","resilience","bond"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Iron Will","Lucky Break","Resilience","Bond"],"antiSynergies":[],"name":"Distortion","alternateName":null,"source":"Jeff Johansen","status":"Live 10.2.0","currentEffect":"Start with 1 Token, up to 2. When the Killer attempts to read your Aura, automatically spend a Token to block the read and suppress your Scratch Marks for 8/10/12 seconds. Regain 1 Token for every 15 seconds spent in chase. Does not trigger while in the Dying State.","activation":["Have at least 1 Token when the Killer attempts to read your Aura.","Spend 15 seconds in chase to regain a Token.","Ends/deactivates when: Aura-block and Scratch Mark suppression end after 8/10/12 seconds."],"patchNote":"Latest live balance change (8.3.2): Reduced the chase time to regain a Token to 15 seconds (was 30); 8.3.0 set 1 starting Token, maximum 2, and 8/10/12 s duration.","plainEnglishSummary":"It automatically blocks Killer Aura reads and hides your Scratch Marks, with tokens replenished during chase.","cooldown":null,"duration":["Aura blocking and Scratch Mark suppression: 8/10/12 seconds by tier."],"tokenOrStackBehavior":"Starts with 1 Token; maximum 2; spends 1 per blocked attempt; regain 1 for each 15 seconds in chase.","oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Does not trigger while in the Dying State."],"sourceCharacter":"Jeff Johansen","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"background-player","rank":25,"tier":"A","roles":["Rescue","Mobility","Team Support"],"summary":"When the Killer picks up a teammate, you can trigger a 50% Haste burst for 5 seconds to reach a save or bodyblock angle.","metaStatus":"Strong","skillLevel":"High","soloQ":3,"swf":5,"unlockPriority":"High","glossaryKeys":["haste","exhausted","dying-state","bodyblock","protection-hit"],"useCases":["Reach a flashlight, Flashbang, pallet, sabotage, or bodyblock angle immediately after a Killer pickup.","Cover large distances quickly when a pickup happens outside your immediate area.","Create coordinated save chains where one Survivor's down becomes a rescue opportunity instead of a guaranteed hook."],"counters":["It only activates when the Killer picks up another Survivor from the Dying State.","You must not already be Exhausted.","Running too early, from too far away, or with no realistic save angle can waste the activation and your positioning.","Hex: Under Your Thumb can cap running Haste while the Hex remains lit."],"pros":["One of the strongest mobility tools for pickup-save builds.","Tier III Exhaustion is only 20 seconds, allowing relatively frequent reuse.","Can completely overturn a down when combined with good timing and a valid save tool."],"cons":["Provides little value if you are not actively playing around saves.","Requires strong positioning, timing, and knowledge of pickup routes.","Can lure players into abandoning generators for low-percentage hero plays."],"analysis":["Background Player takes this position because it can convert a Killer pickup into an immediate threat from a Survivor who otherwise would have been too far away to participate. Five seconds of a 50% Haste bonus is enormous travel distance, and that distance is exactly what flashlight, Flashbang, sabotage, pallet, and bodyblock saves often need.","The perk has a much higher skill requirement than Bond or Off the Record. The user must already understand pickup timing, likely hook routes, save angles, and whether a rescue attempt is actually realistic. Activating the perk and sprinting across the map without a plan can cost more team tempo than the perk ever returns.","Its ceiling rises sharply in SWF. Teammates can call where the down happened, which direction the Killer is facing, whether a pallet is nearby, and whether a sabotage angle exists. That communication turns the Haste burst into a deliberate tool. Solo Q users can still make spectacular saves, but they have less reliable information and a much greater chance of arriving to a situation that cannot be rescued.","Background Player ranks this high because a successful activation can erase a down, which is one of the largest possible swings a Survivor perk can create. It stays outside the top twenty because that value is specialized. Players who are not committed to a save-oriented role will get more reliable value from broader perks."],"verdict":"A specialized but explosive rescue perk. Background Player is mediocre if you merely run fast after pickups, and exceptional if you already know exactly what save angle that speed is supposed to create.","publicationStatus":"published","tags":["Save"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Renato Lyra"},"synergyPerkIds":["bond","flashbang","saboteur","breakout"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:audit-explicit"],"synergies":["Bond","Flashbang","Saboteur","Breakout"],"antiSynergies":[],"name":"Background Player","alternateName":null,"source":"Renato Lyra","status":"Live 10.2.0","currentEffect":"When the Killer picks up another Survivor from the Dying State, the perk activates for 10 seconds. Starting to run during that window grants 50% Haste for 5 seconds. It cannot be used while Exhausted and causes Exhausted for 30/25/20 seconds after use.","activation":["The Killer picks up another Survivor in the Dying State.","Start running within the 10-second window.","You must not be Exhausted.","Ends/deactivates when: Window ends after 10 seconds; Haste ends after 5 seconds."],"patchNote":"Latest live balance change (8.0.0): Reduced the Exhausted duration to 30/25/20 seconds and the Haste bonus to 150% (50% bonus).","plainEnglishSummary":"A Killer pickup of a teammate opens a short window to sprint with a Haste burst.","cooldown":null,"duration":["Activation window: 10 seconds.","Haste: 5 seconds.","Exhausted: 30/25/20 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste","Exhausted"],"specialInteractions":[],"sourceCharacter":"Renato Lyra","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"bond","rank":26,"tier":"A","roles":["Information","Mobility"],"summary":"Continuously see nearby teammates within 36 metres, giving constant information with no trigger, cooldown, or setup.","metaStatus":"Strong","skillLevel":"Low","soloQ":5,"swf":3,"unlockPriority":"Immediate","glossaryKeys":["aura-reading","solo-q","pressure","looping"],"useCases":["Identify who is going for a rescue so you can stay on a generator instead of duplicating effort.","Route chases away from teammates, active generators, and healing zones.","Locate nearby teammates for healing, cooperative repairs, bodyblocks, or coordinated endgame movement."],"counters":["Bond only reveals teammates within range, so it does not provide full-map information.","It tells you where teammates are, not what the Killer is doing unless you infer it from their movement.","Voice-coordinated SWF teams can reproduce part of its information without spending a perk slot."],"pros":["Always active and requires no mechanical execution.","Solves many common Solo Q coordination mistakes before they happen.","Useful for generators, rescues, healing, chase routing, and endgame rather than one narrow task."],"cons":["Provides information rather than a direct speed, health-state, or chase effect.","Lower marginal value in highly coordinated SWF.","The 36-metre range can miss important events on large maps."],"analysis":["Bond earns this position because information that is always available has a reliability advantage over perks that wait for a specific event. The 36-metre Tier III range is large enough to reveal a surprising amount of nearby team structure, and that information improves decisions in almost every phase of a normal match.","Its biggest Solo Q value is preventing duplicated work. Seeing a teammate already moving toward a hook lets you keep repairing. Seeing someone injured approaching your tile tells you a heal may be available. Seeing two teammates on the same side of the map can help you choose a different generator and spread pressure. None of those decisions are dramatic, but they accumulate across an entire Trial.","Bond also improves chase hygiene. A Survivor who can see teammates and active working areas has a much easier time avoiding the classic mistake of dragging the Killer directly onto the team's strongest generator. Experienced players can use the same information for bodyblock timing, protection-hit setups, and deciding whether a nearby teammate is safe to involve in a chase.","It ranks below Off the Record because Bond rarely wins a critical interaction by itself. It makes the user smarter rather than stronger. In SWF, voice communication also reproduces part of the effect. In Solo Q, however, its consistency is exceptional, which is why it remains one of the safest general information perks in the roster."],"verdict":"One of the best pure Solo Q information perks. Bond rarely creates a highlight-reel moment, but it quietly prevents bad rotations, duplicate rescues, and chase-routing mistakes all match long.","publicationStatus":"published","tags":["Solo Q","Positioning"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Dwight Fairfield"},"synergyPerkIds":["kindred","background-player","well-make-it","resilience"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:audit-explicit"],"synergies":["Kindred","Background Player","We'll Make It","Resilience"],"antiSynergies":[],"name":"Bond","alternateName":null,"source":"Dwight Fairfield","status":"Live 10.2.0","currentEffect":"The Auras of other Survivors are revealed to you within 20/28/36 metres.","activation":["Ends/deactivates when: Auras are not shown outside the tier range."],"patchNote":"Latest live balance change (2.3.0): Increased Aura ranges to 20/28/36 metres (was 12/24/36).","plainEnglishSummary":"You see the Auras of nearby teammates.","cooldown":null,"duration":["Continuous while Survivors are within range."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Dwight Fairfield","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"prove-thyself","rank":27,"tier":"A","roles":["Objective","Team Support"],"summary":"Boost cooperative generator repair speed when teammates work within 4 metres, partially offsetting the normal co-op repair penalty.","metaStatus":"Strong","skillLevel":"Low","soloQ":4,"swf":5,"unlockPriority":"Very High","glossaryKeys":["pressure","swf","solo-q"],"useCases":["Finish a high-priority generator quickly when multiple Survivors need to commit together.","Convert coordinated SWF rotations into stronger burst repair windows.","Help recover generator tempo after the team is forced into the same area by hooks or pressure."],"counters":["Provides no benefit when repairing alone.","Grouping multiple Survivors on one generator can make the team vulnerable to area pressure and multi-target Killer powers.","Its bonus partly compensates for cooperative repair inefficiency rather than turning stacked repairs into pure linear scaling."],"pros":["Easy to use and tied to a common objective.","Very strong when a coordinated team intentionally wants one generator finished now.","Extends its bonus to nearby teammates, so only one Survivor needs the perk."],"cons":["Zero value on solo repairs.","Can encourage inefficient generator stacking when spreading out would create more map pressure.","Less predictable in Solo Q because teammates decide whether the trigger exists."],"analysis":["Prove Thyself lands at this position because cooperative repair remains one of the clearest ways to create a short burst of objective pressure. The perk scales with nearby teammates and shares the benefit with them, so one equipped copy can improve an entire stacked generator without requiring every player to dedicate a slot.","Its best use is not simply putting three Survivors on every generator. Dead by Daylight normally rewards splitting pressure because multiple simultaneous generators force the Killer to choose where to respond. Prove Thyself shines when the team has a reason to break that rule: a critical central generator, an unsafe objective that must be completed before the Killer returns, or a coordinated endgame push.","That makes SWF substantially better at extracting value. A premade can call a temporary stack, finish the target, then immediately spread back out. Solo Q teammates may instead sit together too long, turning the perk into an excuse for inefficient map pressure. Bond helps by making those co-op opportunities easier to identify without wandering.","The perk is strong because the activation is simple and the outcome is tangible, but it ranks below Hyperfocus because its ceiling depends on other Survivors being present. A great Survivor perk should ideally remain useful when the team is scattered. Prove Thyself is excellent when the match offers a co-op repair window and completely inert when it does not."],"verdict":"Excellent burst objective pressure when the team deliberately stacks a key generator. Prove Thyself is strongest as a tactical co-op tool, not as permission to repair every generator shoulder-to-shoulder.","publicationStatus":"published","tags":["Co-op","Efficiency"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Dwight Fairfield"},"synergyPerkIds":["deja-vu","hyperfocus","bond","resilience"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:audit-explicit"],"synergies":["Déjà Vu","Hyperfocus","Bond","Resilience"],"antiSynergies":[],"name":"Prove Thyself","alternateName":null,"source":"Dwight Fairfield","status":"Live 10.2.0","currentEffect":"While repairing a Generator, increases Repair speed by a stackable 6/8/10% per other Survivor within 4 metres, up to 18/24/30%. Prove Thyself extends its effect to all Survivors within its range. A Survivor can be affected by only one instance of Prove Thyself at a time.","activation":["Repair a Generator with at least one other Survivor within 4 metres for a bonus to apply.","Ends/deactivates when: The bonus changes as nearby Survivors enter or leave the 4-metre range and ends when the relevant Generator repair stops."],"patchNote":"Latest live balance change (7.1.0): Reduced the Repair speed bonus from 15% to 6/8/10% and removed the cooperative Bloodpoint bonus.","plainEnglishSummary":"Nearby teammates increase Generator repair speed for you and other Survivors in range, up to a tier-specific cap.","cooldown":null,"duration":[],"tokenOrStackBehavior":"Stacks 6/8/10% per other Survivor within 4 metres, capped at 18/24/30% (up to three nearby Survivors). The effect is shared with other Survivors in range.","oncePerTrialOrOtherLimits":"A Survivor can be affected by only one instance of Prove Thyself at a time.","statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Dwight Fairfield","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"fixated","rank":28,"tier":"A","roles":["Chase","Mobility","Stealth"],"summary":"Walk 20% faster at Tier III and see your own Scratch Marks, giving unusually strong control over chase pathing and Sprint Burst management.","metaStatus":"Strong","skillLevel":"Medium–High","soloQ":4,"swf":4,"unlockPriority":"High","glossaryKeys":["looping","exhausted","pressure"],"useCases":["Walk quickly while preserving Sprint Burst instead of giving up enormous map tempo.","Use faster walking during line-of-sight breaks to change direction without broadcasting a full sprint trail.","Read your own Scratch Marks to understand exactly what tracking information the Killer is receiving."],"counters":["Walking remains much slower than sprinting, so poor positioning cannot be rescued by the bonus.","Killers with strong direct tracking, Aura reading, or mobility may care less about subtle Scratch-Mark manipulation.","The perk provides no burst of distance on its own and asks the player to create value through movement decisions."],"pros":["Permanent effect with no cooldown, token, or activation requirement.","One of the best quality-of-life partners for Sprint Burst.","Scales upward as players learn checkspots, pathing, and Scratch-Mark manipulation."],"cons":["Its strongest value is subtle rather than immediately visible.","Less useful for players who sprint everywhere or do not exploit line-of-sight breaks.","Does not directly provide Haste while sprinting or protect a health state."],"analysis":["Fixated rises to this position after the broader candidate review because a permanent 20% walking-speed increase changes more decisions than it first appears to. Walking is normally too slow to use aggressively, but Fixated makes it practical for preserving Sprint Burst, adjusting around checkspots, and repositioning without immediately painting a fresh trail of Scratch Marks.","The perk has an unusual skill curve. Newer players benefit from seeing their own Scratch Marks because it teaches what the Killer sees. Intermediate players may dismiss it once they stop getting lost. Advanced players often rediscover the value because faster walking can be woven into mindgames, corner checks, and Sprint Burst timing without surrendering as much distance.","Its best-known pairing is Sprint Burst. Normally, preserving Sprint Burst by walking everywhere is a serious tempo loss. Fixated reduces that tax and makes selective walking far more practical. The same movement bonus also works while injured, so it does not disappear in the part of the match where chase pathing becomes most important.","Fixated stays below Off the Record because it does not directly prevent a down or solve tunneling. Its value must be manufactured through movement discipline. But unlike many specialized perks, it is always available, and current usage plus community evaluation still reflect that experienced players can squeeze substantial chase and macro value from it."],"verdict":"A deceptively powerful movement perk. Fixated is not about walking everywhere; it is about making selective walking fast enough to become a real chase and Sprint Burst management tool.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Nancy Wheeler"},"synergyPerkIds":["sprint-burst","iron-will","resilience","finesse"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Sprint Burst","Iron Will","Resilience","Finesse"],"antiSynergies":[],"name":"Fixated","alternateName":null,"source":"Nancy Wheeler","status":"Live 10.2.0","currentEffect":"You walk 10/15/20% faster and can see your own Scratch Marks. The walking-speed bonus also applies while injured.","activation":["The walking-speed bonus applies while walking; seeing your own Scratch Marks is passive."],"patchNote":"Latest live balance change (4.5.0): The walking-speed bonus began working while injured as well as while healthy.","plainEnglishSummary":"You walk faster and can see the Scratch Marks you leave, including while injured.","cooldown":null,"duration":["Permanent while in the Trial."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The walking-speed bonus applies while injured following the 4.5.0 change."],"sourceCharacter":"Nancy Wheeler","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"hope","rank":29,"tier":"A","roles":["Endgame","Chase","Mobility"],"summary":"Once the Exit Gates are powered, gain permanent 5% Haste for the rest of the Trial.","metaStatus":"Strong","skillLevel":"Low–Medium","soloQ":4,"swf":5,"unlockPriority":"Medium","glossaryKeys":["haste","looping"],"useCases":["Turn an endgame chase into a much harder catch for standard-speed Killers.","Reach gates, teammates, and rescue positions faster after the generators are completed.","Stack with strong chase fundamentals to convert a narrow endgame lead into an escape."],"counters":["Provides absolutely no value before the Exit Gates are powered.","A match that collapses before endgame leaves the perk completely dead.","Some Killer powers can still ignore or overwhelm the 5% movement advantage.","Hex: Under Your Thumb can cap running Haste while the Hex remains lit."],"pros":["Permanent endgame Haste with no cooldown once activated.","Affects every movement decision after generators are complete, not just one chase.","Can be extremely difficult for basic-attack Killers to overcome in good Survivor hands."],"cons":["Dead perk slot for most of the Trial.","Requires the team to reach powered gates before any value appears.","Weaker than its historical 7% version."],"analysis":["Hope takes this position because 5% permanent Haste is a genuinely powerful effect attached to one of the harshest activation conditions in the game: the team must already have powered the Exit Gates. Before that moment, Hope is not conditional value or reduced value; it is no value at all.","Once active, however, the effect is extremely clean. Movement speed affects every loop, transition, gate rotation, rescue approach, and attempt to reach safety. Against ordinary 115% movement-speed Killers, a strong looper can convert a 5% increase into significantly longer endgame chases because the Killer gains distance more slowly around every structure.","The perk also pairs naturally with Adrenaline. One provides the immediate health-state and burst transition when generators finish; the other stays active for the entire endgame afterward. Coordinated teams can exploit that combination to turn the final generator into a major tempo swing.","Hope has an important consistency limitation because Survivor loadouts need to help the team reach endgame in the first place. A slot that is dead during a losing match can contribute to the reason that match never stabilizes. Hope is therefore a powerful closer rather than a universally strong opener or midgame tool."],"verdict":"An elite endgame closer held back by doing nothing before the gates are powered. If your team reaches the final phase, permanent 5% Haste can make the Killer's last chase dramatically harder.","publicationStatus":"published","tags":["Haste"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["adrenaline","resilience","finesse","five-moves-ahead"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Adrenaline","Resilience","Finesse","Five Moves Ahead"],"antiSynergies":[],"name":"Hope","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"Once the Exit Gates are powered, Hope activates and grants you 3/4/5% Haste for the remainder of the Trial.","activation":["The Exit Gates must be powered.","Ends/deactivates when: The effect ends when the Trial ends."],"patchNote":"Latest live balance change (9.2.0): Reduced Haste from 5/6/7% to 3/4/5%; current duration remains the remainder of the Trial.","plainEnglishSummary":"When the Exit Gates are powered, you move faster until the Trial ends.","cooldown":null,"duration":["Remainder of the Trial after the Exit Gates are powered."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Activates once when the Exit Gates are powered and remains active for the rest of the Trial.","statusEffectsInvolved":["Haste"],"specialInteractions":[],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"hyperfocus","rank":30,"tier":"A","roles":["Objective","Skill Check","Utility"],"summary":"Chain Great Skill Checks to build up to six Tokens that make future checks faster, more frequent, and progressively more rewarding.","metaStatus":"Strong","skillLevel":"Very High","soloQ":4,"swf":5,"unlockPriority":"Medium","glossaryKeys":["pressure","reset"],"useCases":["Accelerate generator progress dramatically when you can consistently hit repeated Great Skill Checks.","Turn long uninterrupted generator windows into substantially more progress than a normal repair perk provides."],"counters":["A Good Skill Check, failed Skill Check, or interruption wipes all Tokens.","The increasing pointer speed makes the perk progressively harder as its reward grows.","Killers that repeatedly force Survivors off generators can erase the setup before it pays off."],"pros":["Among the highest objective-speed ceilings in the Survivor perk roster.","Rewards mechanical consistency rather than relying on the Killer to create a specific situation.","Can snowball its own value because each Token also increases Skill Check frequency."],"cons":["Extremely punishing when the user misses or is interrupted.","Much less reliable for average players than its theoretical ceiling suggests."],"analysis":["Hyperfocus takes this position because its ceiling is absurdly high while its floor can be nearly zero. Each successful Great Skill Check makes the next sequence harder but more rewarding, eventually producing faster pointer movement, more frequent checks, and much larger Great Skill Check progression bonuses.","That feedback loop is why the perk can outperform ordinary repair-speed perks in uninterrupted generator windows. A player who repeatedly lands Greats is not receiving one fixed percentage bonus; they are building a machine that creates more opportunities to generate additional progress. At six Tokens, the effect is strong enough to materially compress generator completion time.","The downside is fragility. One merely Good Skill Check drops the entire stack, as does a failure or any interruption. Killers do not need to understand the exact token count to counter Hyperfocus; forcing the Survivor off the action is enough. The perk therefore performs best when someone else is occupying the Killer and the user has room to settle into the Skill Check rhythm.","It ranks below broader perks because most players cannot access its ceiling consistently without support. The old Stake Out safety-net interaction no longer exists in live 10.2, but spending two slots to make one repair engine reliable is a real opportunity cost. In expert hands, Hyperfocus can look elite; across normal matches, its volatility is the limiting factor."],"verdict":"A monstrous repair perk in skilled hands and a very ordinary one when the Great Skill Check chain collapses. Hyperfocus deserves respect for its ceiling, but not a ranking that ignores how easy that ceiling is to lose.","publicationStatus":"published","tags":["High Ceiling"],"queueRatingStatus":"reviewed","rankRange":[25,40],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Rebecca Chambers"},"synergyPerkIds":["deja-vu","built-to-last","prove-thyself"],"synergyOther":[],"antiSynergyPerkIds":["stake-out"],"archetypeRatings":[{"archetype":"Expert Toolbox repair","grade":"A+/S-","requires":["built-to-last"],"note":"Expert Great-check consistency preserves a much higher ceiling than the average global rank; old Stake Out safety-net assumptions are excluded.","confidence":"Medium"}],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Déjà Vu","Built to Last","Prove Thyself"],"antiSynergies":["Stake Out"],"name":"Hyperfocus","alternateName":null,"source":"Rebecca Chambers","status":"Live 10.2.0","currentEffect":"Succeeding a Great Skill Check while repairing or healing grants 1 Token, up to 6. Each Token increases Skill Check trigger odds by 4% and pointer rotation speed by 4%, up to 24% each. Each Token also increases Great Skill Check bonus progression by 10/20/30% of its base value, up to a total bonus of 60/120/180% by tier. All Tokens are lost after succeeding only a Good Skill Check, failing a Skill Check, or having the action interrupted by any means.","activation":["You must be repairing or healing and succeed a Great Skill Check to gain a Token.","Ends/deactivates when: All Tokens are lost if you succeed only a Good Skill Check.","Ends/deactivates when: All Tokens are lost if you fail a Skill Check.","Ends/deactivates when: All Tokens are lost if the repair or healing action is interrupted by any means."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Consecutive Great Skill Checks while repairing or healing build up to six tokens that increase Skill Check odds, pointer speed, and Great-check progress.","cooldown":null,"duration":[],"tokenOrStackBehavior":"Gain 1 Token per successful Great Skill Check while repairing or healing, up to 6. Tokens increase Skill Check trigger odds and pointer rotation speed by 4% each, and increase Great Skill Check bonus progression by 10/20/30% of its base per token according to tier. All tokens are lost on the listed reset conditions.","oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Applies to both repairing and healing Skill Checks; interruption of either action resets the accumulated Tokens."],"sourceCharacter":"Rebecca Chambers","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"head-on","rank":31,"tier":"A","roles":["Chase","Rescue"],"summary":"After preparing in a Locker for 3 seconds, rush out to stun a nearby Killer for 3 seconds, then become Exhausted.","metaStatus":"Strong","skillLevel":"High","soloQ":3,"swf":5,"unlockPriority":"High","glossaryKeys":["exhausted","looping","bodyblock"],"useCases":["Punish a Killer who checks or passes a prepared Locker during chase.","Coordinate Locker stuns to rescue or protect a teammate moving through the area.","Create mindgames around tiles where the Killer knows a prepared Locker may be occupied."],"counters":["Requires 3 seconds of Locker preparation and cannot be used while Exhausted.","The Killer can bait the rush, approach outside the 2.5-metre stun zone, or simply avoid the Locker.","Idle Crows disable the perk, preventing indefinite passive waiting."],"pros":["A successful 3-second Killer stun is a major chase swing.","Can generate unique rescue and team-play opportunities that ordinary Exhaustion perks cannot.","Threat value can alter how the Killer approaches Locker-heavy structures."],"cons":["Requires preparation and a usable Locker position.","Much less consistent without communication or a deliberate Locker build.","A missed rush can waste the setup and reveal your location."],"analysis":["Head On ranks this position because its ceiling is enormous even though its average activation is far less reliable than conventional Exhaustion perks. A three-second Killer stun can reset a chase, protect another Survivor, interrupt pressure, or create a coordinated save that no simple movement-speed perk could reproduce.","The cost is setup. The Survivor must spend three seconds inside a Locker before the perk is ready, remain free of Exhaustion, and then catch the Killer within a relatively small stun zone. Strong Killers know the perk exists and can bait the rush or approach the Locker from an angle that makes the timing difficult.","SWF raises the perk substantially because teammates can deliberately route a chase toward a prepared Locker. Solo Q cannot guarantee that setup, so Head On often becomes a more personal escape tool or a surprise play. Pairing it with Quick & Quiet also creates much stronger Locker mindgames because the Killer may not know exactly when you entered.","Current usage is unusually high for such a specialized perk, which speaks to both its strength and its appeal. We still rank it below broader perks because a perk slot that requires a specific tile and several seconds of preparation can disappear for long stretches of a match. When it works, however, its impact is unmistakable."],"verdict":"A high-ceiling stun perk that rewards planning and communication. Head On is not reliable enough to rival universal Exhaustion perks, but a successful activation can completely flip a chase or rescue.","publicationStatus":"published","tags":["Stun"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Jane Romero"},"synergyPerkIds":["quick-quiet","deception","flashbang","parental-guidance"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Quick & Quiet","Deception","Flashbang","Parental Guidance"],"antiSynergies":[],"name":"Head On","alternateName":null,"source":"Jane Romero","status":"Live 10.2.0","currentEffect":"After hiding in a Locker for 3 seconds, Head On becomes ready. While not Exhausted and not disabled by Idle Crows, hold Sprint as you exit. If the Killer is within 2.5 metres at the time, they are stunned for 3 seconds. A successful stun makes you Exhausted for 60/50/40 seconds. Missing causes a Loud Noise Notification for the Killer.","activation":["Hide in a Locker for 3 seconds to ready the perk.","Hold Sprint while exiting the Locker.","The Killer must be within 2.5 metres for the stun to connect.","You must not be Exhausted or disabled by Idle Crows.","Ends/deactivates when: A successful stun applies Exhausted, during which Head On cannot be used.","Ends/deactivates when: The ready state does not provide a stun if the Killer is outside the 2.5-metre range."],"patchNote":"Latest live balance change (3.1.0): Added the restriction that Head On cannot be used while the Survivor has accrued Idle Crows; also clarified the Locker rush and stun-zone behavior.","plainEnglishSummary":"After preparing in a Locker, you can stun a nearby Killer by rushing out, then become Exhausted.","cooldown":null,"duration":["Locker preparation: 3 seconds.","Killer stun: 3 seconds.","Exhausted after successful stun: 60/50/40 seconds (Tier I/II/III)."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"No once-per-Trial limit; Exhausted prevents reuse until it expires. Cannot be used while affected by Idle Crows.","statusEffectsInvolved":["Exhausted"],"specialInteractions":["A missed attempt causes a Loud Noise Notification and does not apply Exhausted; Exhausted is applied only on a successful stun (official 3.1.0). Patch 10.2.0 fixed a bug where a failed stun on The Nurse still applied Exhausted and awarded the stun score event.","The restriction against use while affected by Idle Crows is present in the official 3.1.0 live notes."],"sourceCharacter":"Jane Romero","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"quick-quiet","rank":32,"tier":"A","roles":["Chase","Stealth","Locker"],"summary":"Every 15 seconds at Tier III, a Rushed vault or Locker entry/exit can be completely silent and suppress its Loud Noise Notification.","metaStatus":"Strong","skillLevel":"Medium–High","soloQ":4,"swf":4,"unlockPriority":"High","glossaryKeys":["looping","pressure"],"useCases":["Break line of sight and perform a silent Rushed vault so the Killer loses the expected audio and notification cue.","Enter a Locker quickly without advertising the interaction, enabling Head On or stealth mindgames.","Use repeated 15-second-cycle activations during longer chases to create uncertainty at windows and pallets."],"counters":["The 15-second cooldown can be tracked and exploited by an attentive Killer.","Visual confirmation or direct tracking can make the missing sound irrelevant.","A silent action only matters if the Survivor actually creates uncertainty about their route."],"pros":["Patch 8.6.0 improved both cooldown and audio suppression.","Works with windows, pallets, and Locker entries or exits.","Can create genuine chase mindgames without requiring a special item or teammate."],"cons":["Provides no direct speed or health-state protection.","Value depends heavily on line-of-sight breaks and player creativity.","Less useful against Killers whose power or tracking makes the route obvious anyway."],"analysis":["Quick & Quiet lands at this position because the modern version is substantially better than the old 'hide the loud-noise bubble' perk. Since 8.6.0, it suppresses the interaction noises themselves and can be available every 15 seconds at Tier III, which makes it a repeatable chase tool rather than a once-in-a-while stealth gimmick.","Its strength comes from information denial. Killers often make chase decisions using sound before they regain visual contact. If a Survivor disappears behind a wall and the expected vault sound never occurs, the Killer must spend time verifying the route. That hesitation can create more distance than a raw percentage bonus would suggest.","The perk also has excellent build synergy. Head On turns silent Locker entries into a direct stun threat, Lithe can pair a silent vault with immediate distance, and Deception can create competing Locker information. Even without a dedicated build, a good looper can use Quick & Quiet to make familiar tiles harder to read.","It ranks below Head On because the payoff is indirect. Quick & Quiet does not force the Killer to lose time; the Survivor must construct a believable mindgame. That makes it stronger in experienced hands and weaker for players who simply vault silently but continue running along the most obvious path."],"verdict":"A deceptively strong information-denial perk after its modern buffs. Quick & Quiet rewards players who understand how Killers use sound and can turn one missing cue into a real pathing mistake.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Meg Thomas"},"synergyPerkIds":["head-on","lithe","deception","lucky-break"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Head On","Lithe","Deception","Lucky Break"],"antiSynergies":[],"name":"Quick & Quiet","alternateName":null,"source":"Meg Thomas","status":"Live 10.2.0","currentEffect":"When you perform a Rushed action to vault over a Pallet or Window or to enter or exit a Locker, suppresses all noises related to the interaction and its accompanying Loud Noise Notification. The perk has a 25/20/15-second cooldown.","activation":["Perform a Rushed vault over a Pallet or Window, or a Rushed Locker entry or exit.","Ends/deactivates when: The suppression applies to that qualifying interaction; the perk is then unavailable during its cooldown."],"patchNote":"Latest live balance change (8.6.0): Reduced cooldown to 25/20/15 seconds and expanded suppression to all interaction noises instead of only reducing the Loud Noise Notification range.","plainEnglishSummary":"Rushed vaults and Locker entries or exits are silent and do not create their usual Loud Noise Notification, subject to cooldown.","cooldown":"25/20/15 seconds.","duration":["Suppresses noises associated with the qualifying interaction and its accompanying Loud Noise Notification."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Meg Thomas","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"alert","rank":33,"tier":"A","roles":["Information"],"summary":"Whenever the Killer breaks or damages something, see their Aura for up to 5 seconds, with no range or cooldown.","metaStatus":"Strong","skillLevel":"Low","soloQ":5,"swf":4,"unlockPriority":"High","glossaryKeys":["aura-reading","solo-q","pressure"],"useCases":["Identify the Killer's location and direction after pallet breaks, generator kicks, and other Break or Damage actions.","Use repeated Aura reads to decide whether to stay on a generator, rotate, rescue, or prepare for chase.","Learn how different Killers path after breaking resources, making the perk useful for developing game sense."],"counters":["Stealth or Aura-blocking effects can deny the information.","A Killer who performs few qualifying Break or Damage actions gives the perk fewer triggers.","Knowing the Killer's location does not itself create distance if your positioning is already poor."],"pros":["Patch 9.5.0 removed the old range and cooldown limitations.","Requires no setup and can trigger many times in a normal Trial.","Excellent Solo Q information that remains useful even without voice communication."],"cons":["Pure information perk with no direct chase speed, healing, or objective bonus.","Trigger frequency varies by Killer and playstyle.","Aura denial can shut down the perk at important moments."],"analysis":["Alert closes this band at this position because its current 9.5-era design is one of the cleanest information perks in the game. Whenever the Killer performs a qualifying Break or Damage action, their Aura is shown for up to five seconds, and the modern version no longer has the old range or cooldown restrictions.","That makes the perk useful in almost every phase of a Trial. A generator kick can tell you whether the Killer is turning toward your position. A pallet break reveals the direction they take after the animation. Repeated triggers also let Solo Q players infer where pressure is moving without needing teammates to communicate it.","Alert is especially valuable for learning. New and intermediate players can watch how Killers path after breaking pallets and understand when a chase is actually heading toward them. Experienced players use the same information more aggressively, deciding when to greed generator progress or rotate before the Killer can establish pressure.","It ranks below the more directly impactful perks because information only matters if the player acts on it. Alert does not save a health state, accelerate a generator, or shorten a heal by itself. But because it is passive, repeatable, and broadly applicable, it remains more dependable than narrower utility perks."],"verdict":"A superb low-maintenance information perk. Alert's current no-range, no-cooldown design gives Solo Q players repeated Killer-location reads without demanding any setup.","publicationStatus":"published","tags":["Aura Reading","Solo Q"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Feng Min"},"synergyPerkIds":["kindred","bond","troubleshooter","deja-vu"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Kindred","Bond","Troubleshooter","Déjà Vu"],"antiSynergies":[],"name":"Alert","alternateName":null,"source":"Feng Min","status":"Live 10.2.0","currentEffect":"Whenever the Killer performs a Break or Damage Action, their Aura is revealed to you for 3/4/5 seconds.","activation":["The Killer performs a Break or Damage Action.","Ends/deactivates when: Aura reveal ends after the tier duration."],"patchNote":"Latest live balance change (2.3.0): Removed range and cooldown; reveal duration set to 3/4/5 seconds.","plainEnglishSummary":"Breaking or damaging something reveals the Killer's Aura briefly.","cooldown":null,"duration":["Killer Aura reveal: 3/4/5 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Feng Min","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"inner-strength","rank":34,"tier":"A","roles":["Healing","Self-Sustain","Totem"],"summary":"Cleanse a Totem, then spend 8 seconds in a Locker at Tier III to heal yourself by one Health State.","metaStatus":"Strong","skillLevel":"Low–Medium","soloQ":5,"swf":4,"unlockPriority":"High","glossaryKeys":["health-state","reset","broken"],"useCases":["Create a guaranteed self-heal without needing a teammate or Med-Kit.","Bank the heal before a dangerous rescue or objective so it is ready when you later become injured.","Turn necessary Hex cleansing into future personal sustain."],"counters":["Requires finding and cleansing a Totem before the heal becomes available.","Cannot be used while Broken.","The cleansing plus Locker time can be slower overall than simply receiving a fast teammate heal."],"pros":["Reliable self-sustain once charged.","Does not depend on teammate availability or healing coordination.","Can be activated repeatedly by cleansing additional Totems."],"cons":["Consumes Totems that may have value for Boons or other perk interactions.","Requires setup time before any healing value exists.","Locker travel and hiding time can be awkward during active pressure."],"analysis":["Inner Strength ranks this position because it offers one of the cleanest forms of independent Survivor healing. After cleansing a Totem, the player has a banked health state that can be redeemed by spending eight seconds in a Locker at Tier III. That independence is particularly valuable in Solo Q, where finding a teammate for a safe heal can be unreliable.","The perk is strongest when the Totem cleanse was useful anyway. Removing a Hex and receiving a future heal is excellent value because the setup is not wasted time. Even on a Dull Totem, the ability to pre-charge a heal and use it later can support aggressive rescues or generator commitments without needing to carry a Med-Kit.","The real cost is that the full interaction includes finding the Totem, cleansing it, reaching a Locker, and spending the eight seconds inside. If a teammate is standing next to you ready to heal, Inner Strength is often less efficient. It also competes with the team's Boon economy, which can matter in builds centered around Shadow Step or other Boons.","It rates well because the effect is dependable after setup and solves a genuine Solo Q problem. It does not climb higher because that setup cost is real, and good teams can often produce faster resets through ordinary healing."],"verdict":"A dependable self-heal with meaningful setup. Inner Strength shines when independence matters, especially in Solo Q, but it is not free healing once Totem and Locker time are counted.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Nancy Wheeler"},"synergyPerkIds":["quick-quiet","head-on","counterforce","overzealous"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Quick & Quiet","Head On","Counterforce","Overzealous"],"antiSynergies":[],"name":"Inner Strength","alternateName":null,"source":"Nancy Wheeler","status":"Live 10.2.0","currentEffect":"After you cleanse a Totem, Inner Strength activates. While active, hide in a Locker for 10/9/8 seconds to heal yourself by one Health State. It deactivates after healing and cannot be used while you are Broken. Cleansing another Totem can activate it again.","activation":["Cleanse a Totem; blessing a Totem does not activate the perk.","While activated, remain hidden inside a Locker for 10/9/8 seconds.","You must not be suffering from Broken when attempting to use it.","Ends/deactivates when: Deactivates after healing one Health State."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Cleansing a Totem lets you heal one Health State by hiding in a Locker for the tier's stated time.","cooldown":null,"duration":["Locker channel required: 10/9/8 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Broken (prevents use)"],"specialInteractions":["Heals the user by one Health State, including Dying to Injured or Injured to Healthy."],"sourceCharacter":"Nancy Wheeler","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"boon-shadow-step","rank":35,"tier":"A","roles":["Boon","Stealth"],"summary":"Bless a Totem to hide Survivor Scratch Marks and Auras from the Killer within 24 metres, with a short linger after leaving.","metaStatus":"Strong","skillLevel":"Medium","soloQ":4,"swf":5,"unlockPriority":"High","glossaryKeys":["aura-reading","looping"],"useCases":["Create a chase zone where the Killer cannot rely on Scratch Marks after losing line of sight.","Protect teammates from Aura-reading effects while they repair, heal, or rotate through the Boon area.","Use multi-floor or dense indoor geometry to make tracking dramatically harder."],"counters":["The Killer can snuff the Boon and remove the entire setup.","Value is geographically limited to the Totem's 24-metre radius plus the brief linger.","Open maps with poor Totem placement may provide much weaker chase coverage."],"pros":["Benefits every Survivor in range rather than only the perk owner.","Simultaneously attacks Scratch-Mark tracking and Aura reading.","Can become oppressive on indoor or multi-floor maps where the Boon covers several useful areas."],"cons":["Requires Totem setup time.","Location and map layout heavily influence value.","A single Killer snuff can erase the investment until you re-bless."],"analysis":["Boon: Shadow Step ranks this position because its best maps turn a modest-looking radius into a serious tracking problem. Survivors within 24 metres leave no Scratch Marks and have their Auras hidden from the Killer, attacking two of the most common information channels at the same time.","The effect becomes particularly strong around line-of-sight-heavy structures. When a Survivor disappears around a corner, the Killer cannot simply follow Scratch Marks to recover the route. On multi-floor maps, the radius can also cover a surprising amount of playable space vertically, giving the entire team access to the protection.","The weakness is infrastructure. Someone must find a Totem, spend time blessing it, and hope the location is actually useful. The Killer can also snuff it, turning the perk into repeated setup time if the Boon is placed somewhere obvious or strategically important.","It ranks below individual always-available perks because the map and Totem placement introduce inconsistency. But when Shadow Step controls a good section of the map, it can affect several Survivors and multiple chases from one perk slot, giving it a team ceiling that many stealth perks cannot match."],"verdict":"A map-dependent team stealth engine. Shadow Step can be merely decent on a poor Totem and brutally disruptive when its radius covers a strong chase or indoor area.","publicationStatus":"published","tags":["Information Denial"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Mikaela Reid"},"synergyPerkIds":["boon-circle-of-healing","boon-steadfast","quick-quiet","lucky-break"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Boon: Circle of Healing","Boon: Steadfast","Quick & Quiet","Lucky Break"],"antiSynergies":[],"name":"Boon: Shadow Step","alternateName":null,"source":"Mikaela Reid","status":"Live 10.2.0","currentEffect":"Bless a Dull or Hex Totem. Survivors within 24 metres have their Scratch Marks and Auras hidden from the Killer; these effects linger for 2/3/4 seconds after leaving the radius.","activation":["Bless a Dull or Hex Totem.","Be within 24 metres for the main concealment effect.","Ends/deactivates when: Effects end after leaving range and the tiered linger time, or when the totem is snuffed."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"A Boon Totem hides nearby Survivors' Scratch Marks and Auras from the Killer.","cooldown":null,"duration":["Scratch Mark/Aura concealment lingers 2/3/4 seconds outside the radius."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"One active Boon Totem per Survivor; equipped Boons apply to that totem.","statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Mikaela Reid","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"built-to-last","rank":36,"tier":"A","roles":["Item","Objective"],"summary":"Recharge a depleted Item in a Locker up to three times, restoring 99%, then 66%, then 33% of its maximum Charges.","metaStatus":"Strong","skillLevel":"Low","soloQ":4,"swf":4,"unlockPriority":"High","glossaryKeys":["reset"],"useCases":["Extend strong Toolboxes across multiple generators instead of exhausting them in one burst.","Turn high-quality Med-Kits into repeated healing resources throughout the Trial.","Recharge Flashlights or other limited Items when their utility is central to the build."],"counters":["Requires the Item to be depleted and costs 10 seconds in a Locker at Tier III for each recharge.","The restored percentage drops on each successive use.","A weak Item remains a weak Item even when you receive more Charges."],"pros":["Can multiply the total value of a strong Item several times over.","Works with multiple Item categories rather than one narrow strategy.","Predictable and easy to execute once the Item is depleted."],"cons":["Requires bringing or finding an Item worth recharging.","Locker downtime can erase part of the gained efficiency.","Third recharge is much smaller than the first."],"analysis":["Built to Last earns this position because Items are some of the strongest resources Survivors can bring, and the perk effectively stretches those resources far beyond their normal charge limit. A first recharge to 99% is especially powerful with a high-quality Toolbox or Med-Kit that was already optimized with Add-ons.","The perk becomes more impressive when the Item itself creates time savings. Recharging a Toolbox costs Locker time, but the restored charges can accelerate generators later. Recharging a Med-Kit can create additional independent heals. The correct question is not whether ten Locker seconds are free; it is whether the restored Item produces more strategic value than those seconds cost.","Its flexibility also matters. Built to Last is not locked to generators or healing, and it can support Flashlight-focused players as well. That makes the perk a resource multiplier whose exact role changes with the Item equipped, which is useful for players who already build intentionally around their inventory.","It stays below the stronger universal perks because the slot is only as good as the Item being recycled. A player who enters with a poor Item, loses it, or never needs its extra Charges gets limited value. With premium equipment, however, Built to Last can quietly produce a huge amount of additional match resources."],"verdict":"A powerful Item multiplier whose ceiling depends on what you bring. Built to Last turns premium gear into a much deeper resource pool, at the cost of deliberate Locker downtime.","publicationStatus":"published","tags":["Resource"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Felix Richter"},"synergyPerkIds":["hyperfocus","botany-knowledge"],"synergyOther":["Flashlights"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Hyperfocus","Botany Knowledge","Flashlights"],"antiSynergies":[],"name":"Built to Last","alternateName":null,"source":"Felix Richter","status":"Live 10.2.0","currentEffect":"While in a Locker with a depleted Item, after 14/12/10 seconds by perk tier restore its Charges to 99% of maximum. Each subsequent use restores 66%, then 33%. Can be used a maximum of 3 times per Trial.","activation":["Enter a Locker with a depleted Item.","Ends/deactivates when: Each recharge ends when its tier time has elapsed or the interaction is interrupted.","Ends/deactivates when: Cannot be used after three activations."],"patchNote":"Latest live balance change (9.1.0): Final 9.1.0 live notes set the time spent in a Locker to 14/12/10 seconds; this differs from the 12/10/8-second PTB value.","plainEnglishSummary":"After 14/12/10 seconds by perk tier, a Locker recharge restores a depleted Item to 99%; later activations restore 66% and then 33%, up to 3 uses per Trial.","cooldown":null,"duration":["First recharge after 14/12/10 seconds by tier; restores 99%.","Second use restores 66%; third use restores 33%."],"tokenOrStackBehavior":"Uses are limited to 3 per Trial; recharge amount declines from 99% to 66% to 33%.","oncePerTrialOrOtherLimits":"Maximum 3 uses per Trial.","statusEffectsInvolved":[],"specialInteractions":["The recovered Item Charges are based on the held Item's maximum."],"sourceCharacter":"Felix Richter","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"}]);
